statements:
create extension if not exists pgcrypto;

create type public.user_role as enum ('client','coach','staff','admin');
create type public.coach_status as enum ('applicant','under_review','verification','approved','active','review_required','suspended','inactive');
create type public.client_status as enum ('prospect','onboarding','active','inactive','completed');
create type public.order_status as enum ('pending','paid','processing','in_progress','review','completed','cancelled','refunded');
create type public.deliverable_status as enum ('pending','draft','internal_review','client_review','revision','approved','delivered');
create type public.opportunity_status as enum ('discovered','screened','verified','published','expired','archived');
create type public.application_status as enum ('identified','interested','preparing','submitted','interview','assessment','offer','rejected','withdrawn','accepted');

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, role public.user_role not null default 'client', full_name text not null, email text, phone text, country text, timezone text, avatar_url text, bio text, linkedin_url text, status text not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.clients (id uuid primary key default gen_random_uuid(), profile_id uuid not null unique references public.profiles(id) on delete cascade, status public.client_status not null default 'prospect', preferred_coach_id uuid, onboarding_completed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.coaches (id uuid primary key default gen_random_uuid(), profile_id uuid not null unique references public.profiles(id) on delete cascade, professional_title text, professional_bio text, years_experience integer check (years_experience is null or years_experience >= 0), coaching_experience_years integer check (coaching_experience_years is null or coaching_experience_years >= 0), methodology text, languages text[] not null default '{}', credentials text[] not null default '{}', linkedin_url text, website_url text, availability_summary text, timezone text, capacity integer check (capacity is null or capacity >= 0), application_status public.coach_status not null default 'applicant', verified_at timestamptz, approved_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.clients add constraint clients_preferred_coach_fk foreign key (preferred_coach_id) references public.coaches(id) on delete set null;
create table public.staff (id uuid primary key default gen_random_uuid(), profile_id uuid not null unique references public.profiles(id) on delete cascade, department text, job_title text, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.career_profiles (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, version integer not null default 1 check (version > 0), professional_summary text, current_level text, target_roles text[] not null default '{}', target_industries text[] not null default '{}', target_locations text[] not null default '{}', career_interests text[] not null default '{}', leadership_experience text, development_gaps text[] not null default '{}', is_current boolean not null default true, ai_generated boolean not null default false, ai_model text, ai_prompt_version text, ai_generated_at timestamptz, human_reviewed boolean not null default false, human_reviewed_by uuid references public.profiles(id) on delete set null, human_reviewed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(client_id, version));
create table public.education (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, institution text not null, degree text, field_of_study text, start_date date, end_date date, description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.experience (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, organization text not null, job_title text not null, location text, employment_type text, start_date date, end_date date, is_current boolean not null default false, description text, achievements text[] not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.skills (id uuid primary key default gen_random_uuid(), name text not null unique, category text, description text, created_at timestamptz not null default now());
create table public.client_skills (client_id uuid not null references public.clients(id) on delete cascade, skill_id uuid not null references public.skills(id) on delete cascade, proficiency text, years_experience numeric(5,2), evidence text, source text, created_at timestamptz not null default now(), primary key(client_id, skill_id));
create table public.career_goals (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, goal text not null, priority integer not null default 1 check (priority > 0), target_date date, status text not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.specialties (id uuid primary key default gen_random_uuid(), name text not null unique, description text, active boolean not null default true, created_at timestamptz not null default now());
create table public.coach_specialties (coach_id uuid not null references public.coaches(id) on delete cascade, specialty_id uuid not null references public.specialties(id) on delete cascade, years_experience integer check (years_experience is null or years_experience >= 0), created_at timestamptz not null default now(), primary key(coach_id, specialty_id));
create table public.coach_availability (id uuid primary key default gen_random_uuid(), coach_id uuid not null references public.coaches(id) on delete cascade, day_of_week integer not null check (day_of_week between 0 and 6), start_time time not null, end_time time not null, timezone text not null, active boolean not null default true, created_at timestamptz not null default now(), check (end_time > start_time));
create table public.coach_matches (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, coach_id uuid not null references public.coaches(id) on delete cascade, match_type text not null default 'client_selected', match_score numeric(5,2), match_reason text, status text not null default 'recommended', selected_by_client boolean not null default false, assigned_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.coaching_sessions (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, coach_id uuid not null references public.coaches(id) on delete restrict, scheduled_at timestamptz not null, duration_minutes integer not null default 60 check (duration_minutes > 0), meeting_url text, status text not null default 'scheduled', session_notes text, action_summary text, human_reviewed boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.coaching_action_plans (id uuid primary key default gen_random_uuid(), session_id uuid references public.coaching_sessions(id) on delete cascade, client_id uuid not null references public.clients(id) on delete cascade, coach_id uuid references public.coaches(id) on delete set null, action text not null, due_date date, status text not null default 'open', completed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.coaching_outcomes (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, coach_id uuid references public.coaches(id) on delete set null, outcome_type text not null, outcome_description text, measured_value text, measured_at timestamptz not null default now(), created_at timestamptz not null default now());
create table public.services (id uuid primary key default gen_random_uuid(), name text not null unique, slug text not null unique, category text not null, description text, price numeric(12,2), currency text not null default 'USD', active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.orders (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete restrict, service_id uuid not null references public.services(id) on delete restrict, status public.order_status not null default 'pending', amount numeric(12,2), currency text not null default 'USD', payment_reference text, paid_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.deliverables (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, client_id uuid not null references public.clients(id) on delete cascade, name text not null, file_path text, status public.deliverable_status not null default 'pending', ai_generated boolean not null default false, ai_model text, ai_prompt_version text, human_reviewed boolean not null default false, human_reviewed_by uuid references public.profiles(id) on delete set null, human_reviewed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.opportunities (id uuid primary key default gen_random_uuid(), title text not null, organization_name text, opportunity_type text, description text, url text, source_name text, source_url text, deadline timestamptz, status public.opportunity_status not null default 'discovered', verified_at timestamptz, published_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.opportunity_matches (id uuid primary key default gen_random_uuid(), opportunity_id uuid not null references public.opportunities(id) on delete cascade, client_id uuid not null references public.clients(id) on delete cascade, match_score numeric(5,2), match_reason text, ai_generated boolean not null default false, human_reviewed boolean not null default false, created_at timestamptz not null default now(), unique(opportunity_id, client_id));
create table public.applications (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, opportunity_id uuid references public.opportunities(id) on delete set null, target_role text, organization_name text, status public.application_status not null default 'identified', deadline timestamptz, submitted_at timestamptz, outcome_notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.leads (id uuid primary key default gen_random_uuid(), full_name text, email text, phone text, organization_name text, source text, interest text, score integer check (score is null or score between 0 and 100), status text not null default 'new', owner_profile_id uuid references public.profiles(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null unique, organization_type text, website_url text, country text, description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.partnerships (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, partnership_type text, status text not null default 'prospect', start_date date, end_date date, owner_profile_id uuid references public.profiles(id) on delete set null, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.assessments (id uuid primary key default gen_random_uuid(), name text not null, description text, assessment_type text, version text not null default '1.0', active boolean not null default true, created_at timestamptz not null default now());
create table public.assessment_questions (id uuid primary key default gen_random_uuid(), assessment_id uuid not null references public.assessments(id) on delete cascade, question text not null, question_type text not null, options jsonb, position integer not null, created_at timestamptz not null default now(), unique(assessment_id, position));
create table public.assessment_responses (id uuid primary key default gen_random_uuid(), assessment_id uuid not null references public.assessments(id) on delete cascade, question_id uuid not null references public.assessment_questions(id) on delete cascade, client_id uuid not null references public.clients(id) on delete cascade, response jsonb, created_at timestamptz not null default now(), unique(question_id, client_id));
create table public.assessment_results (id uuid primary key default gen_random_uuid(), assessment_id uuid not null references public.assessments(id) on delete cascade, client_id uuid not null references public.clients(id) on delete cascade, score numeric(8,2), result jsonb not null default '{}', ai_generated boolean not null default false, human_reviewed boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.career_pathways (id uuid primary key default gen_random_uuid(), name text not null unique, description text, target_roles text[] not null default '{}', target_industries text[] not null default '{}', active boolean not null default true, created_at timestamptz not null default now());
create table public.client_career_pathways (client_id uuid not null references public.clients(id) on delete cascade, pathway_id uuid not null references public.career_pathways(id) on delete cascade, fit_score numeric(5,2), recommendation_reason text, selected boolean not null default false, created_at timestamptz not null default now(), primary key(client_id, pathway_id));
create table public.audit_logs (id uuid primary key default gen_random_uuid(), actor_profile_id uuid references public.profiles(id) on delete set null, action text not null, table_name text, record_id uuid, metadata jsonb not null default '{}', created_at timestamptz not null default now());

create index clients_profile_id_idx on public.clients(profile_id); create index coaches_profile_id_idx on public.coaches(profile_id); create index career_profiles_client_current_idx on public.career_profiles(client_id, is_current); create index education_client_idx on public.education(client_id); create index experience_client_idx on public.experience(client_id); create index client_skills_skill_idx on public.client_skills(skill_id); create index career_goals_client_idx on public.career_goals(client_id); create index coach_specialties_specialty_idx on public.coach_specialties(specialty_id); create index coach_availability_coach_idx on public.coach_availability(coach_id); create index coach_matches_client_idx on public.coach_matches(client_id); create index coach_matches_coach_idx on public.coach_matches(coach_id); create index coaching_sessions_client_idx on public.coaching_sessions(client_id); create index coaching_sessions_coach_idx on public.coaching_sessions(coach_id); create index coaching_sessions_scheduled_idx on public.coaching_sessions(scheduled_at); create index coaching_action_plans_client_idx on public.coaching_action_plans(client_id); create index coaching_outcomes_client_idx on public.coaching_outcomes(client_id); create index orders_client_idx on public.orders(client_id); create index deliverables_client_idx on public.deliverables(client_id); create index opportunities_status_deadline_idx on public.opportunities(status, deadline); create index opportunity_matches_client_idx on public.opportunity_matches(client_id); create index applications_client_idx on public.applications(client_id); create index applications_opportunity_idx on public.applications(opportunity_id); create index leads_status_idx on public.leads(status); create index partnerships_organization_idx on public.partnerships(organization_id); create index assessment_responses_client_idx on public.assessment_responses(client_id); create index assessment_results_client_idx on public.assessment_results(client_id); create index client_career_pathways_pathway_idx on public.client_career_pathways(pathway_id); create index audit_logs_actor_idx on public.audit_logs(actor_profile_id); create index audit_logs_record_idx on public.audit_logs(table_name, record_id);

create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end; $$;

alter table public.profiles enable row level security; alter table public.clients enable row level security; alter table public.coaches enable row level security; alter table public.staff enable row level security; alter table public.career_profiles enable row level security; alter table public.education enable row level security; alter table public.experience enable row level security; alter table public.skills enable row level security; alter table public.client_skills enable row level security; alter table public.career_goals enable row level security; alter table public.specialties enable row level security; alter table public.coach_specialties enable row level security; alter table public.coach_availability enable row level security; alter table public.coach_matches enable row level security; alter table public.coaching_sessions enable row level security; alter table public.coaching_action_plans enable row level security; alter table public.coaching_outcomes enable row level security; alter table public.services enable row level security; alter table public.orders enable row level security; alter table public.deliverables enable row level security; alter table public.opportunities enable row level security; alter table public.opportunity_matches enable row level security; alter table public.applications enable row level security; alter table public.leads enable row level security; alter table public.organizations enable row level security; alter table public.partnerships enable row level security; alter table public.assessments enable row level security; alter table public.assessment_questions enable row level security; alter table public.assessment_responses enable row level security; alter table public.assessment_results enable row level security; alter table public.career_pathways enable row level security; alter table public.client_career_pathways enable row level security; alter table public.audit_logs enable row level security;

grant usage on schema public to anon, authenticated;
grant select on public.services, public.specialties, public.skills, public.opportunities, public.career_pathways, public.coaches, public.coach_specialties, public.assessments, public.assessment_questions to anon, authenticated;
grant select, insert, update, delete on public.profiles, public.clients, public.coaches, public.staff, public.career_profiles, public.education, public.experience, public.skills, public.client_skills, public.career_goals, public.specialties, public.coach_specialties, public.coach_availability, public.coach_matches, public.coaching_sessions, public.coaching_action_plans, public.coaching_outcomes, public.services, public.orders, public.deliverables, public.opportunities, public.opportunity_matches, public.applications, public.leads, public.organizations, public.partnerships, public.assessments, public.assessment_questions, public.assessment_responses, public.assessment_results, public.career_pathways, public.client_career_pathways, public.audit_logs to authenticated;
grant all on all tables in schema public to service_role;

create policy "public can view active services" on public.services for select to anon, authenticated using (active = true);
create policy "public can view active specialties" on public.specialties for select to anon, authenticated using (active = true);
create policy "public can view skills" on public.skills for select to anon, authenticated using (true);
create policy "public can view published opportunities" on public.opportunities for select to anon, authenticated using (status = 'published');
create policy "public can view active pathways" on public.career_pathways for select to anon, authenticated using (active = true);
create policy "public can view approved coaches" on public.coaches for select to anon, authenticated using (application_status in ('approved','active'));
create policy "public can view coach specialties" on public.coach_specialties for select to anon, authenticated using (exists (select 1 from public.coaches c where c.id = coach_id and c.application_status in ('approved','active')));
create policy "users can view own profile" on public.profiles for select to authenticated using ((select auth.uid()) = id);
create policy "users can create own profile" on public.profiles for insert to authenticated with check ((select auth.uid()) = id);
create policy "users can update own profile" on public.profiles for update to authenticated using ((select auth.uid()) = id) with check ((select auth.uid()) = id);

create policy "clients can view own client record" on public.clients for select to authenticated using (profile_id = (select auth.uid()));
create policy "clients can update own client record" on public.clients for update to authenticated using (profile_id = (select auth.uid())) with check (profile_id = (select auth.uid()));
create policy "clients can view own career profiles" on public.career_profiles for select to authenticated using (exists (select 1 from public.clients c where c.id = client_id and c.profile_id = (select auth.uid())));
create policy "clients can manage own career profiles" on public.career_profiles for all to authenticated using (exists (select 1 from public.clients c where c.id = client_id and c.profile_id = (select auth.uid()))) with check (exists (select 1 from public.clients c where c.id = client_id and c.profile_id = (select auth.uid())));
create policy "clients can manage own education" on public.education for all to authenticated using (exists (select 1 from public.clients c where c.id = client_id and c.profile_id = (select auth.uid()))) with check (exists (select 1 from public.clients c where c.id = client_id and c.profile_id = (select auth.uid())));
create policy "clients can manage own experience" on public.experience for all to authenticated using (exists (select 1 from public.clients c where c.id = client_id and c.profile_id = (select auth.uid()))) with check (exists (select 1 from public.clients c where c.id = client_id and c.profile_id = (select auth.uid())));
create policy "clients can manage own skills" on public.client_skills for all to authenticated using (exists (select 1 from public.clients c where c.id = client_id and c.profile_id = (select auth.uid()))) with check (exists (select 1 from public.clients c where c.id = client_id and c.profile_id = (select auth.uid())));
create policy "clients can manage own goals" on public.career_goals for all to authenticated using (exists (select 1 from public.clients c where c.id = client_id and c.profile_id = (select auth.uid()))) with check (exists (select 1 from public.clients c where c.id = client_id and c.profile_id = (select auth.uid())));
create policy "clients can view own matches" on public.coach_matches for select to authenticated using (exists (select 1 from public.clients c where c.id = client_id and c.profile_id = (select auth.uid())));
create policy "clients can view own sessions" on public.coaching_sessions for select to authenticated using (exists (select 1 from public.clients c where c.id = client_id and c.profile_id = (select auth.uid())));
create policy "clients can view own action plans" on public.coaching_action_plans for select to authenticated using (exists (select 1 from public.clients c where c.id = client_id and c.profile_id = (select auth.uid())));
create policy "clients can update own action plans" on public.coaching_action_plans for update to authenticated using (exists (select 1 from public.clients c where c.id = client_id and c.profile_id = (select auth.uid()))) with check (exists (select 1 from public.clients c where c.id = client_id and c.profile_id = (select auth.uid())));
create policy "clients can view own outcomes" on public.coaching_outcomes for select to authenticated using (exists (select 1 from public.clients c where c.id = client_id and c.profile_id = (select auth.uid())));
create policy "clients can view own orders" on public.orders for select to authenticated using (exists (select 1 from public.clients c where c.id = client_id and c.profile_id = (select auth.uid())));
create policy "clients can view own deliverables" on public.deliverables for select to authenticated using (exists (select 1 from public.clients c where c.id = client_id and c.profile_id = (select auth.uid())));
create policy "clients can view own opportunity matches" on public.opportunity_matches for select to authenticated using (exists (select 1 from public.clients c where c.id = client_id and c.profile_id = (select auth.uid())));
create policy "clients can view own applications" on public.applications for select to authenticated using (exists (select 1 from public.clients c where c.id = client_id and c.profile_id = (select auth.uid())));
create policy "clients can manage own applications" on public.applications for all to authenticated using (exists (select 1 from public.clients c where c.id = client_id and c.profile_id = (select auth.uid()))) with check (exists (select 1 from public.clients c where c.id = client_id and c.profile_id = (select auth.uid())));
create policy "clients can view own assessment responses" on public.assessment_responses for select to authenticated using (exists (select 1 from public.clients c where c.id = client_id and c.profile_id = (select auth.uid())));
create policy "clients can manage own assessment responses" on public.assessment_responses for all to authenticated using (exists (select 1 from public.clients c where c.id = client_id and c.profile_id = (select auth.uid()))) with check (exists (select 1 from public.clients c where c.id = client_id and c.profile_id = (select auth.uid())));
create policy "clients can view own assessment results" on public.assessment_results for select to authenticated using (exists (select 1 from public.clients c where c.id = client_id and c.profile_id = (select auth.uid())));
create policy "clients can view own pathway matches" on public.client_career_pathways for select to authenticated using (exists (select 1 from public.clients c where c.id = client_id and c.profile_id = (select auth.uid())));

create policy "coaches can update own coach profile" on public.coaches for update to authenticated using (profile_id = (select auth.uid())) with check (profile_id = (select auth.uid()));
create policy "coaches can view own specialties" on public.coach_specialties for select to authenticated using (exists (select 1 from public.coaches c where c.id = coach_id and c.profile_id = (select auth.uid())));
create policy "coaches can manage own availability" on public.coach_availability for all to authenticated using (exists (select 1 from public.coaches c where c.id = coach_id and c.profile_id = (select auth.uid()))) with check (exists (select 1 from public.coaches c where c.id = coach_id and c.profile_id = (select auth.uid())));
create policy "coaches can view assigned matches" on public.coach_matches for select to authenticated using (exists (select 1 from public.coaches c where c.id = coach_id and c.profile_id = (select auth.uid())));
create policy "coaches can view assigned sessions" on public.coaching_sessions for select to authenticated using (exists (select 1 from public.coaches c where c.id = coach_id and c.profile_id = (select auth.uid())));
create policy "coaches can update assigned sessions" on public.coaching_sessions for update to authenticated using (exists (select 1 from public.coaches c where c.id = coach_id and c.profile_id = (select auth.uid()))) with check (exists (select 1 from public.coaches c where c.id = coach_id and c.profile_id = (select auth.uid())));
create policy "coaches can manage assigned action plans" on public.coaching_action_plans for all to authenticated using (exists (select 1 from public.coaches c where c.id = coach_id and c.profile_id = (select auth.uid()))) with check (exists (select 1 from public.coaches c where c.id = coach_id and c.profile_id = (select auth.uid())));
create policy "coaches can manage assigned outcomes" on public.coaching_outcomes for all to authenticated using (exists (select 1 from public.coaches c where c.id = coach_id and c.profile_id = (select auth.uid()))) with check (exists (select 1 from public.coaches c where c.id = coach_id and c.profile_id = (select auth.uid())));

