create or replace view public.ai_observability_dashboard with (security_invoker = true) as
select
  date_trunc('hour', occurred_at) as hour,
  workflow,
  service_scope,
  model_name,
  count(*) as total_events,
  count(*) filter (where status = 'completed') as completed_events,
  count(*) filter (where status in ('failed','blocked')) as failed_or_blocked_events,
  count(*) filter (where safety_flag) as safety_events,
  count(*) filter (where human_override) as human_overrides,
  round(avg(latency_ms))::integer as avg_latency_ms,
  round(avg(quality_score),4) as avg_quality_score,
  coalesce(sum(input_tokens),0) as input_tokens,
  coalesce(sum(output_tokens),0) as output_tokens,
  coalesce(sum(total_tokens),0) as total_tokens,
  coalesce(sum(estimated_cost),0)::numeric(14,6) as estimated_cost
from public.ai_observability_events
group by date_trunc('hour', occurred_at), workflow, service_scope, model_name;

