create or replace function public.apply_approved_profile_sync_proposal(p_proposal_id uuid) returns jsonb
language plpgsql security invoker set search_path=public as $$
declare v public.profile_sync_proposals%rowtype; v_user uuid:=auth.uid();
begin
 if not exists(select 1 from public.profiles where id=v_user and status='active' and role in ('coach','admin','staff')) then raise exception 'Authorized staff access required'; end if;
 select * into v from public.profile_sync_proposals where id=p_proposal_id for update;
 if not found then raise exception 'Proposal not found'; end if;
 if v.status<>'approved' then raise exception 'Only approved proposals can be applied'; end if;
 if v.evidence_item_id is not null and not exists(select 1 from public.evidence_items where id=v.evidence_item_id and verification_status='verified') then raise exception 'Source evidence is no longer verified'; end if;
 if v.target_entity='career_profile' then
   update public.career_profiles cp set professional_summary=case when v.target_field='professional_summary' then v.proposed_value->>'value' else cp.professional_summary end,leadership_experience=case when v.target_field='leadership_experience' then v.proposed_value->>'value' else cp.leadership_experience end,target_role=case when v.target_field='target_role' then v.proposed_value->>'value' else cp.target_role end,target_industry=case when v.target_field='target_industry' then v.proposed_value->>'value' else cp.target_industry end,target_location=case when v.target_field='target_location' then v.proposed_value->>'value' else cp.target_location end,current_job_title=case when v.target_field='current_job_title' then v.proposed_value->>'value' else cp.current_job_title end,current_industry=case when v.target_field='current_industry' then v.proposed_value->>'value' else cp.current_industry end,current_location=case when v.target_field='current_location' then v.proposed_value->>'value' else cp.current_location end,last_intelligence_run_at=now(),updated_at=now() where cp.id=coalesce(v.target_record_id,(select id from public.career_profiles where client_id=v.client_id and is_current=true order by updated_at desc limit 1));
   if not found then raise exception 'Current career profile not found'; end if;
 else raise exception 'Target entity % requires a dedicated typed sync handler before application',v.target_entity; end if;
 update public.profile_sync_proposals set status='applied',applied_at=now(),updated_at=now() where id=p_proposal_id;
 return jsonb_build_object('proposal_id',p_proposal_id,'status','applied','target_entity',v.target_entity,'target_field',v.target_field);
end; $$;
