create or replace function public.apply_approved_profile_sync_proposal(p_proposal_id uuid) returns jsonb
language plpgsql security invoker set search_path=public as $$
declare v public.profile_sync_proposals%rowtype; v_user uuid:=auth.uid(); v_record uuid; v_value jsonb;
begin
 if not exists(select 1 from public.profiles where id=v_user and status='active' and role in ('coach','admin','staff')) then raise exception 'Authorized staff access required'; end if;
 select * into v from public.profile_sync_proposals where id=p_proposal_id for update;
 if not found then raise exception 'Proposal not found'; end if;
 if v.status not in ('approved','proposed') then raise exception 'Only approved proposals can be applied'; end if;
 if v.evidence_item_id is not null and not exists(select 1 from public.evidence_items where id=v.evidence_item_id and verification_status='verified') then raise exception 'Source evidence is no longer verified'; end if;
 v_value:=v.proposed_value;
 if v.target_entity='experience' then
   if v.target_record_id is null then
     if nullif(v_value->>'organization','') is null or nullif(v_value->>'job_title','') is null then raise exception 'New experience requires organization and job_title'; end if;
     insert into public.experience(client_id,organization,job_title,location,employment_type,start_date,end_date,is_current,description,achievements)
     values(v.client_id,v_value->>'organization',v_value->>'job_title',v_value->>'location',(v_value->>'employment_type'),nullif(v_value->>'start_date','')::date,nullif(v_value->>'end_date','')::date,coalesce((v_value->>'is_current')::boolean,false),v_value->>'description',coalesce(array(select jsonb_array_elements_text(v_value->'achievements')),array[]::text[])) returning id into v_record;
   else
     update public.experience e set organization=coalesce(v_value->>'organization',e.organization),job_title=coalesce(v_value->>'job_title',e.job_title),location=coalesce(v_value->>'location',e.location),employment_type=coalesce(v_value->>'employment_type',e.employment_type),start_date=case when v_value ? 'start_date' then nullif(v_value->>'start_date','')::date else e.start_date end,end_date=case when v_value ? 'end_date' then nullif(v_value->>'end_date','')::date else e.end_date end,is_current=case when v_value ? 'is_current' then (v_value->>'is_current')::boolean else e.is_current end,description=coalesce(v_value->>'description',e.description),achievements=case when v_value ? 'achievements' then coalesce(array(select jsonb_array_elements_text(v_value->'achievements')),array[]::text[]) else e.achievements end,updated_at=now() where e.id=v.target_record_id and e.client_id=v.client_id returning e.id into v_record;
     if v_record is null then raise exception 'Experience record not found for client'; end if;
   end if;
 elsif v.target_entity='education' then
   if v.target_record_id is null then
     if nullif(v_value->>'institution','') is null then raise exception 'New education requires institution'; end if;
     insert into public.education(client_id,institution,degree,field_of_study,start_date,end_date,description)
     values(v.client_id,v_value->>'institution',v_value->>'degree',v_value->>'field_of_study',nullif(v_value->>'start_date','')::date,nullif(v_value->>'end_date','')::date,v_value->>'description') returning id into v_record;
   else
     update public.education e set institution=coalesce(v_value->>'institution',e.institution),degree=coalesce(v_value->>'degree',e.degree),field_of_study=coalesce(v_value->>'field_of_study',e.field_of_study),start_date=case when v_value ? 'start_date' then nullif(v_value->>'start_date','')::date else e.start_date end,end_date=case when v_value ? 'end_date' then nullif(v_value->>'end_date','')::date else e.end_date end,description=coalesce(v_value->>'description',e.description),updated_at=now() where e.id=v.target_record_id and e.client_id=v.client_id returning e.id into v_record;
     if v_record is null then raise exception 'Education record not found for client'; end if;
   end if;
 elsif v.target_entity='client_skill' then
   if v.target_record_id is null then raise exception 'New client_skill requires target_record_id=skill id'; end if;
   if not exists(select 1 from public.skills where id=v.target_record_id) then raise exception 'Skill not found'; end if;
   insert into public.client_skills(client_id,skill_id,proficiency,years_experience,evidence,source)
   values(v.client_id,v.target_record_id,v_value->>'proficiency',nullif(v_value->>'years_experience','')::numeric,v_value->>'evidence',coalesce(v_value->>'source','verified_evidence'))
   on conflict(client_id,skill_id) do update set proficiency=coalesce(excluded.proficiency,client_skills.proficiency),years_experience=coalesce(excluded.years_experience,client_skills.years_experience),evidence=coalesce(excluded.evidence,client_skills.evidence),source=coalesce(excluded.source,client_skills.source);
   v_record:=v.target_record_id;
 elsif v.target_entity='career_goal' then
   if v.target_record_id is null then
     if nullif(v_value->>'goal','') is null then raise exception 'New career goal requires goal'; end if;
     insert into public.career_goals(client_id,goal,priority,target_date,status)
     values(v.client_id,v_value->>'goal',coalesce(nullif(v_value->>'priority','')::integer,1),nullif(v_value->>'target_date','')::date,coalesce(nullif(v_value->>'status',''),'active')) returning id into v_record;
   else
     update public.career_goals g set goal=coalesce(v_value->>'goal',g.goal),priority=coalesce(nullif(v_value->>'priority','')::integer,g.priority),target_date=case when v_value ? 'target_date' then nullif(v_value->>'target_date','')::date else g.target_date end,status=coalesce(v_value->>'status',g.status),updated_at=now() where g.id=v.target_record_id and g.client_id=v.client_id returning g.id into v_record;
     if v_record is null then raise exception 'Career goal not found for client'; end if;
   end if;
 elsif v.target_entity='career_profile' then
   update public.career_profiles cp set professional_summary=case when v.target_field='professional_summary' then v_value->>'value' else cp.professional_summary end,leadership_experience=case when v.target_field='leadership_experience' then v_value->>'value' else cp.leadership_experience end,target_role=case when v.target_field='target_role' then v_value->>'value' else cp.target_role end,target_industry=case when v.target_field='target_industry' then v_value->>'value' else cp.target_industry end,target_location=case when v.target_field='target_location' then v_value->>'value' else cp.target_location end,current_job_title=case when v.target_field='current_job_title' then v_value->>'value' else cp.current_job_title end,current_industry=case when v.target_field='current_industry' then v_value->>'value' else cp.current_industry end,current_location=case when v.target_field='current_location' then v_value->>'value' else cp.current_location end,last_intelligence_run_at=now(),updated_at=now() where cp.id=coalesce(v.career_profile_id,(select id from public.career_profiles where client_id=v.client_id and is_current=true order by updated_at desc limit 1));
   if not found then raise exception 'Current career profile not found'; end if;
   v_record:=coalesce(v.career_profile_id,(select id from public.career_profiles where client_id=v.client_id and is_current=true order by updated_at desc limit 1));
 else raise exception 'Unsupported target entity'; end if;
 insert into public.profile_sync_provenance(proposal_id,client_id,target_entity,target_record_id,target_field,source_evidence_item_id,source_document_id,source_location,applied_value,applied_by)
 select v.id,v.client_id,v.target_entity,v_record,v.target_field,v.evidence_item_id,d.id,coalesce(v.source_location,df.source_location),v.proposed_value,v_user
 from (select v.evidence_item_id,v.id,v.client_id,v.target_entity,v.target_field,v.source_location,v.proposed_value) x
 left join public.evidence_items ei on ei.id=x.evidence_item_id
 left join public.document_facts df on df.id=ei.source_id and ei.source_type='document_fact'
 left join public.documents d on d.id=df.document_id;
 update public.profile_sync_proposals set status='applied',applied_at=now(),updated_at=now(),reviewed_by=coalesce(reviewed_by,v_user),reviewed_at=coalesce(reviewed_at,now()) where id=p_proposal_id;
 return jsonb_build_object('proposal_id',v.id,'status','applied','target_entity',v.target_entity,'target_record_id',v_record);
end; $$;
