create or replace function public.create_dynamic_intake_session(p_service_request_id uuid) returns uuid language plpgsql security invoker set search_path=public as $$ declare v_client uuid;v_profile uuid;v_session uuid; begin select client_id into v_client from public.service_requests where id=p_service_request_id; if v_client is null then raise exception 'Service request not found';end if; if not exists(select 1 from public.clients c where c.id=v_client and c.profile_id=(select auth.uid())) and not exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in('admin','staff','coach')) then raise exception 'Not authorized';end if; select id into v_profile from public.career_profiles where client_id=v_client and is_current=true limit 1; select id into v_session from public.dynamic_intake_sessions where service_request_id=p_service_request_id and status in('active','awaiting_client','awaiting_review','ready') order by created_at desc limit 1; if v_session is not null then return v_session;end if; insert into public.dynamic_intake_sessions(client_id,service_request_id,career_profile_id,created_by) values(v_client,p_service_request_id,v_profile,(select auth.uid())) returning id into v_session;return v_session;end;$$;
create or replace function public.generate_dynamic_intake_requirements(p_session_id uuid) returns integer language plpgsql security invoker set search_path=public as $$ declare v_session record;v_req public.service_requests%rowtype;v_profile public.career_profiles%rowtype;v_count integer:=0; begin select s.* into v_session from public.dynamic_intake_sessions s where s.id=p_session_id;if not found then raise exception 'Session not found';end if;if not exists(select 1 from public.clients c where c.id=v_session.client_id and c.profile_id=(select auth.uid())) and not exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in('admin','staff','coach')) then raise exception 'Not authorized';end if;select * into v_req from public.service_requests where id=v_session.service_request_id;select * into v_profile from public.career_profiles where id=v_session.career_profile_id;if nullif(trim(coalesce(v_req.objective,'')),'') is null then insert into public.dynamic_intake_requirements(session_id,client_id,service_request_id,requirement_type,field_name,requirement,rationale,priority,source) values(p_session_id,v_session.client_id,v_req.id,'goal','objective','A clear service objective is required.','The service must have a measurable intended outcome.','high','service_request');v_count:=v_count+1;end if;if nullif(trim(coalesce(v_req.target_role,'')),'') is null and nullif(trim(coalesce(v_profile.target_role,'')),'') is null and coalesce(array_length(v_profile.target_roles,1),0)=0 then insert into public.dynamic_intake_requirements(session_id,client_id,service_request_id,requirement_type,field_name,requirement,rationale,priority,source) values(p_session_id,v_session.client_id,v_req.id,'goal','target_role','Target career role must be defined.','Target-role information determines positioning, evidence, keywords, and service recommendations.','critical','service_request');v_count:=v_count+1;end if;if nullif(trim(coalesce(v_req.target_country,'')),'') is null and nullif(trim(coalesce(v_profile.target_location,'')),'') is null and coalesce(array_length(v_profile.target_locations,1),0)=0 then insert into public.dynamic_intake_requirements(session_id,client_id,service_request_id,requirement_type,field_name,requirement,priority,source) values(p_session_id,v_session.client_id,v_req.id,'preference','target_location','Preferred target country or location is needed.','Geography can materially affect career strategy and opportunity matching.','medium','service_request');v_count:=v_count+1;end if;if nullif(trim(coalesce(v_profile.professional_summary,'')),'') is null then insert into public.dynamic_intake_requirements(session_id,client_id,service_request_id,requirement_type,field_name,requirement,rationale,priority,source) values(p_session_id,v_session.client_id,v_req.id,'profile_field','professional_summary','Professional background summary is missing.','A reliable profile summary supports downstream service delivery.','high','system');v_count:=v_count+1;end if;if not exists(select 1 from public.evidence_items e where e.client_id=v_session.client_id and e.verification_status='verified') then insert into public.dynamic_intake_requirements(session_id,client_id,service_request_id,requirement_type,requirement,rationale,priority,source) values(p_session_id,v_session.client_id,v_req.id,'evidence','At least one verified evidence source should support the profile.','Career deliverables should be grounded in verifiable client evidence.','high','system');v_count:=v_count+1;end if;update public.dynamic_intake_sessions set updated_at=now(),current_step='requirements' where id=p_session_id;return v_count;end;$$;
create or replace function public.generate_next_dynamic_intake_question(p_session_id uuid) returns uuid language plpgsql security invoker set search_path=public as $$ declare v_req record;v_q uuid;v_seq integer; begin if not exists(select 1 from public.dynamic_intake_sessions s join public.clients c on c.id=s.client_id where s.id=p_session_id and (c.profile_id=(select auth.uid()) or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in('admin','staff','coach')))) then raise exception 'Not authorized';end if;select coalesce(max(sequence_no),0)+1 into v_seq from public.dynamic_intake_questions where session_id=p_session_id;select r.* into v_req from public.dynamic_intake_requirements r where r.session_id=p_session_id and r.status='open' order by case r.priority when 'critical' then 1 when 'high' then 2 when 'medium' then 3 else 4 end,r.created_at limit 1;if not found then update public.dynamic_intake_sessions set status='ready',current_step='complete',completion_score=1,updated_at=now() where id=p_session_id;return null;end if;insert into public.dynamic_intake_questions(session_id,requirement_id,client_id,sequence_no,question_text,question_type,required,rationale) values(p_session_id,v_req.id,v_req.client_id,v_seq,case v_req.field_name when 'target_role' then 'What specific career role or roles are you targeting?' when 'target_location' then 'Which country, city, or geographic market are you targeting?' when 'professional_summary' then 'Please briefly describe your professional background, strongest experience, and the direction you want to pursue.' when 'objective' then 'What specific outcome do you want to achieve through this service?' else 'Please provide the information needed to complete your Career Intelligence Profile.' end,case when v_req.requirement_type='evidence' then 'file' else 'textarea' end,true,v_req.rationale) returning id into v_q;update public.dynamic_intake_sessions set last_question_id=v_q,status='awaiting_client',current_step='questioning',updated_at=now() where id=p_session_id;return v_q;end;$$;
revoke execute on function public.create_dynamic_intake_session(uuid),public.generate_dynamic_intake_requirements(uuid),public.generate_next_dynamic_intake_question(uuid) from public,anon;grant execute on function public.create_dynamic_intake_session(uuid),public.generate_dynamic_intake_requirements(uuid),public.generate_next_dynamic_intake_question(uuid) to authenticated;

