 exists(select 1 from public.ai_service_workflow_executions e join public.ai_service_delivery_runs r on r.id=e.delivery_run_id join public.clients c on c.id=r.client_id join public.profiles p on p.id=auth.uid() where e.id=execution_id and c.profile_id=p.id)
 or exists(select 1 from public.profiles p where p.id=auth.uid() and p.status='active' and p.role in ('admin','staff'))
 or exists(select 1 from public.ai_service_workflow_executions e join public.ai_service_delivery_runs r on r.id=e.delivery_run_id join public.service_requests sr on sr.id=r.service_request_id join public.profiles p on p.id=auth.uid() where e.id=execution_id and sr.assigned_coach=p.id and p.status='active' and p.role='coach')
);

create or replace function public.evaluate_ai_workflow_step_quality(p_step_run_id uuid)
returns jsonb language plpgsql security invoker set search_path=public as $$
declare x public.ai_service_workflow_step_runs%rowtype; e public.ai_service_workflow_executions%rowtype; r public.ai_service_delivery_runs%rowtype; g record; v_user uuid:=auth.uid(); v_role text; v_score numeric; v_pass boolean; v_critical_failed boolean:=false; v_failed boolean:=false; v_results jsonb:='[]'::jsonb; v_summary jsonb;
begin
 select role into v_role from public.profiles where id=v_user and status='active';
 select * into x from public.ai_service_workflow_step_runs where id=p_step_run_id;
 if not found then raise exception 'Step run not found'; end if;
 select * into e from public.ai_service_workflow_executions where id=x.execution_id;
 select * into r from public.ai_service_delivery_runs where id=e.delivery_run_id;
 if not (v_role in ('admin','staff') or (v_role='coach' and exists(select 1 from public.service_requests sr where sr.id=r.service_request_id and sr.assigned_coach=v_user))) then raise exception 'Authorized reviewer access required'; end if;
 if x.output_snapshot is null then raise exception 'Step output is required before quality evaluation'; end if;
 for g in select * from public.ai_quality_gates where active=true and (run_type in ('service_delivery','workflow_step','end_to_end') or run_type='intake') order by severity desc,name loop
   v_score:=1; v_pass:=true;
   if g.criterion='no_fabrication' then
     if coalesce(x.output_snapshot->>'human_review_required','true')='false' then v_score:=0; v_pass:=false; end if;
   elsif g.criterion='evidence_grounding' or g.criterion='source_traceability' then
     if jsonb_typeof(x.output_snapshot->'facts')='array' then
       select case when count(*)=0 then 1 else avg(case when coalesce(f->>'source_location','')<>'' then 1 else 0 end) end into v_score from jsonb_array_elements(x.output_snapshot->'facts') f;
       v_pass:=v_score>=g.threshold;
     else v_score:=0; v_pass:=false; end if;
   elsif g.criterion='service_relevance' then
     if coalesce(x.output_snapshot->>'service_relevance','')='' then v_score:=0; v_pass:=false; end if;
   elsif g.criterion='human_review_gate' then
     if coalesce(x.output_snapshot->>'human_review_required','true')<>'true' then v_score:=0; v_pass:=false; end if;
   end if;
   insert into public.ai_workflow_quality_evaluations(step_run_id,execution_id,gate_id,score,passed,severity,rationale,evaluator_type)
   values(x.id,e.id,g.id,v_score,v_pass,g.severity,case when v_pass then 'Quality criterion satisfied by structured output checks.' else 'Quality criterion failed or required evidence was not present in the structured output.' end,'rule')
   on conflict(step_run_id,gate_id) do update set score=excluded.score,passed=excluded.passed,severity=excluded.severity,rationale=excluded.rationale,evaluator_type=excluded.evaluator_type;
   v_results:=v_results||jsonb_build_array(jsonb_build_object('gate',g.name,'criterion',g.criterion,'score',v_score,'passed',v_pass,'severity',g.severity));
   if not v_pass then v_failed:=true; if g.severity='critical' then v_critical_failed:=true; end if; end if;
 end loop;
 v_summary:=jsonb_build_object('passed',not v_failed,'critical_failure',v_critical_failed,'results',v_results);
 if v_critical_failed then
   update public.ai_service_workflow_step_runs set status='blocked',quality_results=v_results,error_message='Critical AI quality gate failure',completed_at=now(),updated_at=now() where id=x.id;
   update public.ai_service_workflow_executions set status='blocked',quality_results=v_results,error_message='Critical AI quality gate failure',updated_at=now() where id=e.id;
   update public.ai_service_delivery_runs set status='blocked',workflow_stage='quality_gate_blocked',quality_summary=v_summary,error_message='Critical AI quality gate failure',updated_at=now() where id=r.id;
 elsif v_failed then
   update public.ai_service_workflow_step_runs set status='awaiting_review',quality_results=v_results,updated_at=now() where id=x.id;
   update public.ai_service_workflow_executions set status='awaiting_review',quality_results=v_results,updated_at=now() where id=e.id;
   update public.ai_service_delivery_runs set status='awaiting_human_review',workflow_stage='quality_review',quality_summary=v_summary,updated_at=now() where id=r.id;
 else
   update public.ai_service_workflow_step_runs set quality_results=v_results,updated_at=now() where id=x.id;
   update public.ai_service_workflow_executions set quality_results=v_results,updated_at=now() where id=e.id;
   update public.ai_service_delivery_runs set quality_summary=v_summary,updated_at=now() where id=r.id;
 end if;
 return v_summary;
end; $$;
revoke all on function public.evaluate_ai_workflow_step_quality(uuid) from public,anon,authenticated;
grant execute on function public.evaluate_ai_workflow_step_quality(uuid) to authenticated;

create or replace function public.complete_ai_workflow_step_after_quality(p_step_run_id uuid)
returns jsonb language plpgsql security invoker set search_path=public as $$
declare x public.ai_service_workflow_step_runs%rowtype; e public.ai_service_workflow_executions%rowtype; r public.ai_service_delivery_runs%rowtype; n public.ai_service_workflow_steps%rowtype; q record; v_user uuid:=auth.uid(); v_role text; v_critical boolean:=false; v_failed boolean:=false; v_next uuid;
begin
 select role into v_role from public.profiles where id=v_user and status='active';
 select * into x from public.ai_service_workflow_step_runs where id=p_step_run_id for update;
 if not found then raise exception 'Step run not found'; end if;
 select * into e from public.ai_service_workflow_executions where id=x.execution_id for update;
 select * into r from public.ai_service_delivery_runs where id=e.delivery_run_id;
 if not (v_role in ('admin','staff') or (v_role='coach' and exists(select 1 from public.service_requests sr where sr.id=r.service_request_id and sr.assigned_coach=v_user))) then raise exception 'Authorized reviewer access required'; end if;
 for q in select * from public.ai_workflow_quality_evaluations where step_run_id=x.id loop
   if not q.passed then v_failed:=true; if q.severity='critical' then v_critical:=true; end if; end if;
 end loop;
 if v_critical then raise exception 'Critical quality gate failed; workflow cannot advance'; end if;
 if v_failed then
   update public.ai_service_workflow_step_runs set status='awaiting_review',updated_at=now() where id=x.id;
   update public.ai_service_workflow_executions set status='awaiting_review',updated_at=now() where id=e.id;
   update public.ai_service_delivery_runs set status='awaiting_human_review',workflow_stage='quality_review',updated_at=now() where id=r.id;
   return jsonb_build_object('status','awaiting_review','human_review_required',true);
 end if;
 select * into n from public.ai_service_workflow_steps where workflow_id=e.workflow_id and active=true and step_order>x.step_order order by step_order limit 1;
 if n.id is null then
   update public.ai_service_workflow_step_runs set status='completed',completed_at=now(),updated_at=now() where id=x.id;
   update public.ai_service_workflow_executions set status='completed',completed_at=now(),updated_at=now() where id=e.id;
   update public.ai_service_delivery_runs set status='awaiting_human_review',workflow_stage='final_human_review',completed_at=now(),updated_at=now() where id=r.id;
   return jsonb_build_object('status','completed','human_review_required',true);
 end if;
 update public.ai_service_workflow_step_runs set status='completed',completed_at=now(),updated_at=now() where id=x.id;
 insert into public.ai_service_workflow_step_runs(execution_id,step_id,step_order,status,input_snapshot)
 values(e.id,n.id,n.step_order,'pending',jsonb_build_object('previous_output',x.output_snapshot,'execution_context',e.context_snapshot)) on conflict(execution_id,step_id) do nothing returning id into v_next;
 update public.ai_service_workflow_executions set status='running',current_step_order=n.step_order,updated_at=now() where id=e.id;
 update public.ai_service_delivery_runs set status='running',workflow_stage='step_'||n.step_order,updated_at=now() where id=r.id;
 return jsonb_build_object('status','next_step_ready','step_run_id',v_next,'step_order',n.step_order,'step_key',n.step_key);
end; $$;
revoke all on function public.complete_ai_workflow_step_after_quality(uuid) from public,anon,authenticated;
grant execute on function public.complete_ai_workflow_step_after_quality(uuid) to authenticated;

