 execution_id uuid not null references public.ai_agent_executions(id) on delete cascade,
 agent_id uuid not null references public.ai_agent_registry(id) on delete cascade,
 config_type text not null,
 config_key text not null,
 config_version integer not null,
 configuration jsonb not null default '{}'::jsonb,
 captured_at timestamptz not null default now(),
 unique(execution_id,config_type,config_key)
);
create index if not exists idx_ai_agent_config_snapshots_execution on public.ai_agent_configuration_snapshots(execution_id);
alter table public.ai_agent_configuration_snapshots enable row level security;
