create policy ai_agent_config_snapshots_select on public.ai_agent_configuration_snapshots for select to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.status='active' and p.role in ('admin','staff','coach')) or exists(select 1 from public.ai_agent_executions e where e.id=execution_id and e.created_by=auth.uid()));

create or replace function public.bind_ai_agent_configuration(p_agent_key text,p_config_type text,p_config_key text,p_required boolean default true)
returns uuid language plpgsql security invoker set search_path=public as $$
declare u uuid:=auth.uid(); role_name text; a public.ai_agent_registry%rowtype; v_id uuid;
begin
 select role into role_name from public.profiles where id=u and status='active';
 if role_name not in ('admin','staff') then raise exception 'Admin or staff access required'; end if;
 select * into a from public.ai_agent_registry where agent_key=p_agent_key and active=true;
 if not found then raise exception 'AI agent not found'; end if;
 if not exists(select 1 from public.ai_configuration_registry where config_type=p_config_type and config_key=p_config_key and active=true) then raise exception 'Active configuration registry entry not found'; end if;
 insert into public.ai_agent_configuration_bindings(agent_id,config_type,config_key,required,active) values(a.id,p_config_type,p_config_key,p_required,true)
 on conflict(agent_id,config_type,config_key) do update set required=excluded.required,active=true returning id into v_id;
 return v_id;
end; $$;
revoke all on function public.bind_ai_agent_configuration(text,text,text,boolean) from public,anon,authenticated;
grant execute on function public.bind_ai_agent_configuration(text,text,text,boolean) to authenticated;

create or replace function public.capture_ai_agent_configuration_snapshot(p_execution_id uuid)
returns integer language plpgsql security invoker set search_path=public as $$
declare u uuid:=auth.uid(); role_name text; e public.ai_agent_executions%rowtype; b record; r public.ai_configuration_registry%rowtype; v public.ai_configuration_versions%rowtype; n integer:=0;
begin
 select role into role_name from public.profiles where id=u and status='active';
 if role_name not in ('admin','staff','coach') then raise exception 'Authorized service team access required'; end if;
 select * into e from public.ai_agent_executions where id=p_execution_id for update; if not found then raise exception 'AI agent execution not found'; end if;
 if role_name='coach' and e.created_by<>u then raise exception 'Coach may only capture own executions'; end if;
 for b in select * from public.ai_agent_configuration_bindings where agent_id=e.agent_id and active=true order by config_type,config_key loop
   select * into r from public.ai_configuration_registry where config_type=b.config_type and config_key=b.config_key and active=true;
   if not found then if b.required then raise exception 'Required active configuration missing: % / %',b.config_type,b.config_key; else continue; end if; end if;
   select * into v from public.ai_configuration_versions where registry_id=r.id and version=r.active_version and status='active';
   if not found then if b.required then raise exception 'Required active configuration version missing: % / %',b.config_type,b.config_key; else continue; end if; end if;
   insert into public.ai_agent_configuration_snapshots(execution_id,agent_id,config_type,config_key,config_version,configuration) values(e.id,e.agent_id,b.config_type,b.config_key,v.version,v.configuration)
   on conflict(execution_id,config_type,config_key) do update set config_version=excluded.config_version,configuration=excluded.configuration,captured_at=now();
   n:=n+1;
 end loop;
 return n;
end; $$;
revoke all on function public.capture_ai_agent_configuration_snapshot(uuid) from public,anon,authenticated;
grant execute on function public.capture_ai_agent_configuration_snapshot(uuid) to authenticated;

