create or replace function public.request_ai_agent_execution(p_agent_key text,p_workflow_key text default null,p_trigger_source text default 'manual',p_input_payload jsonb default '{}'::jsonb)
returns uuid language plpgsql security invoker set search_path=public as $$
declare u uuid:=auth.uid(); role_name text; a public.ai_agent_registry%rowtype; w public.ai_agent_workflows%rowtype; req uuid;
begin
 select role into role_name from public.profiles where id=u and status='active';
 if role_name not in ('admin','staff','coach') then raise exception 'Authorized service team access required'; end if;
 select * into a from public.ai_agent_registry where agent_key=p_agent_key and active=true;
 if not found then raise exception 'Active AI agent not found'; end if;
 if role_name='coach' and a.owner_role not in ('coach','staff') then raise exception 'Coach cannot request this agent'; end if;
 if p_workflow_key is not null then
   select * into w from public.ai_agent_workflows where agent_id=a.id and workflow_key=p_workflow_key and active=true order by version desc limit 1;
   if not found then raise exception 'Active workflow not found for agent'; end if;
 end if;
 insert into public.ai_agent_execution_requests(agent_id,workflow_id,requested_by,trigger_source,input_payload,status,authorized_at)
 values(a.id,case when w.id is null then null else w.id end,u,p_trigger_source,coalesce(p_input_payload,'{}'::jsonb),'authorized',now()) returning id into req;
 insert into public.ai_agent_execution_events(request_id,event_type,event_data,actor_id) values(req,'requested',jsonb_build_object('agent_key',a.agent_key,'workflow_key',p_workflow_key),u), (req,'authorized',jsonb_build_object('autonomy_level',a.autonomy_level,'human_approval_required',a.human_approval_required),u);
 return req;
end; $$;
revoke all on function public.request_ai_agent_execution(text,text,text,jsonb) from public,anon,authenticated;
grant execute on function public.request_ai_agent_execution(text,text,text,jsonb) to authenticated;

create or replace function public.prepare_ai_agent_execution(p_request_id uuid)
returns jsonb language plpgsql security invoker set search_path=public as $$
declare u uuid:=auth.uid(); role_name text; r public.ai_agent_execution_requests%rowtype; a public.ai_agent_registry%rowtype; e uuid; snapshot_count integer;
begin
 select role into role_name from public.profiles where id=u and status='active'; if role_name not in ('admin','staff','coach') then raise exception 'Authorized service team access required'; end if;
 select * into r from public.ai_agent_execution_requests where id=p_request_id for update; if not found then raise exception 'Execution request not found'; end if;
 if role_name='coach' and r.requested_by<>u then raise exception 'Coach may only prepare own requests'; end if;
 if r.status not in ('authorized','prepared') then raise exception 'Request is not ready for preparation'; end if;
 if r.execution_id is null then
   insert into public.ai_agent_executions(agent_id,workflow_id,status,trigger_source,input_snapshot,human_review_required,human_review_status,created_by) select r.agent_id,r.workflow_id,'authorized',r.trigger_source,r.input_payload,a.human_approval_required,case when a.human_approval_required then 'pending' else 'not_required' end,u from public.ai_agent_registry a where a.id=r.agent_id returning id into e;
   update public.ai_agent_execution_requests set execution_id=e,status='prepared' where id=r.id;
 else e:=r.execution_id; update public.ai_agent_execution_requests set status='prepared' where id=r.id;
 end if;
 select public.capture_ai_agent_configuration_snapshot(e) into snapshot_count;
 insert into public.ai_agent_execution_events(request_id,execution_id,event_type,event_data,actor_id) values(r.id,e,'configuration_captured',jsonb_build_object('snapshot_count',snapshot_count),u);
 return jsonb_build_object('request_id',r.id,'execution_id',e,'snapshot_count',snapshot_count,'status','prepared');
end; $$;
revoke all on function public.prepare_ai_agent_execution(uuid) from public,anon,authenticated;
grant execute on function public.prepare_ai_agent_execution(uuid) to authenticated;

create or replace function public.transition_ai_agent_execution(p_request_id uuid,p_status text,p_event_data jsonb default '{}'::jsonb)
returns jsonb language plpgsql security invoker set search_path=public as $$
declare u uuid:=auth.uid(); role_name text; r public.ai_agent_execution_requests%rowtype; e public.ai_agent_executions%rowtype;
begin
 select role into role_name from public.profiles where id=u and status='active'; if role_name not in ('admin','staff','coach') then raise exception 'Authorized service team access required'; end if;
 if p_status not in ('running','awaiting_quality','awaiting_human_review','completed','blocked','failed','cancelled') then raise exception 'Invalid execution status'; end if;
 select * into r from public.ai_agent_execution_requests where id=p_request_id for update; if not found then raise exception 'Execution request not found'; end if;
 if role_name='coach' and r.requested_by<>u then raise exception 'Coach may only transition own requests'; end if;
 if r.execution_id is null then raise exception 'Execution has not been prepared'; end if;
 update public.ai_agent_execution_requests set status=p_status,completed_at=case when p_status in ('completed','blocked','failed','cancelled') then now() else completed_at end where id=r.id;
 update public.ai_agent_executions set status=p_status,started_at=case when p_status='running' and started_at is null then now() else started_at end,completed_at=case when p_status in ('completed','blocked','failed','cancelled') then now() else completed_at end,updated_at=now() where id=r.execution_id returning * into e;
 insert into public.ai_agent_execution_events(request_id,execution_id,event_type,event_data,actor_id) values(r.id,r.execution_id,case p_status when 'running' then 'started' when 'awaiting_quality' then 'quality_started' when 'awaiting_human_review' then 'human_review' when 'completed' then 'completed' when 'blocked' then 'blocked' when 'failed' then 'failed' when 'cancelled' then 'cancelled' end,coalesce(p_event_data,'{}'::jsonb),u);
 return jsonb_build_object('request_id',r.id,'execution_id',r.execution_id,'status',p_status);
end; $$;
revoke all on function public.transition_ai_agent_execution(uuid,text,jsonb) from public,anon,authenticated;
grant execute on function public.transition_ai_agent_execution(uuid,text,jsonb) to authenticated;

create or replace function public.record_ai_service_workflow_step_output(p_step_run_id uuid, p_output jsonb, p_error text default null)
returns jsonb
language plpgsql
set search_path to public
as $$
declare x public.ai_service_workflow_step_runs%rowtype; e public.ai_service_workflow_executions%rowtype; r public.ai_service_delivery_runs%rowtype; v_user uuid:=auth.uid(); v_role text;
begin
 select role into v_role from public.profiles where id=v_user and status='active';
 select * into x from public.ai_service_workflow_step_runs where id=p_step_run_id for update;
 if not found then raise exception 'Step run not found'; end if;
 select * into e from public.ai_service_workflow_executions where id=x.execution_id;
 select * into r from public.ai_service_delivery_runs where id=e.delivery_run_id;
 if not (v_role in ('admin','staff') or (v_role='coach' and exists(select 1 from public.service_requests sr where sr.id=r.service_request_id and sr.assigned_coach=v_user))) then raise exception 'Authorized coach/staff access required'; end if;
 if x.status not in ('running','pending') then raise exception 'Step is not writable from status %',x.status; end if;
 update public.ai_service_workflow_step_runs set status='running',output_snapshot=p_output,error_message=p_error,updated_at=now() where id=x.id;
 update public.ai_service_workflow_executions set status='running',output_snapshot=p_output,error_message=p_error,updated_at=now() where id=e.id;
 update public.ai_service_delivery_runs set status='running',output_snapshot=p_output,error_message=p_error,updated_at=now() where id=r.id;
 return jsonb_build_object('step_run_id',x.id,'execution_id',e.id,'status','output_recorded','quality_evaluation_required',true);
end; $$;

revoke execute on function public.record_ai_service_workflow_step_output(uuid,jsonb,text) from public;
grant execute on function public.record_ai_service_workflow_step_output(uuid,jsonb,text) to authenticated;

