create or replace view public.ai_governance_runtime_health with (security_invoker=true) as
select
 (select count(*) from public.ai_agent_registry where active=true) as active_agents,
 (select count(*) from public.ai_agent_executions where status='running') as running_executions,
 (select count(*) from public.ai_agent_executions where status='awaiting_quality') as awaiting_quality,
 (select count(*) from public.ai_agent_executions where status='awaiting_human_review') as awaiting_human_review,
 (select count(*) from public.ai_agent_executions where status='failed' and created_at >= now()-interval '24 hours') as failed_24h,
 (select count(*) from public.ai_agent_executions where status='blocked' and created_at >= now()-interval '24 hours') as blocked_24h,
 (select count(*) from public.ai_workflow_quality_evaluations where passed=false and created_at >= now()-interval '24 hours') as quality_failures_24h,
 (select count(*) from public.ai_workflow_quality_evaluations where passed=false and severity='critical' and created_at >= now()-interval '24 hours') as critical_quality_failures_24h,
 (select count(*) from public.ai_operational_alerts where status='open') as open_alerts,
 (select coalesce(sum(total_tokens),0) from public.ai_usage_events where created_at >= now()-interval '24 hours') as tokens_24h,
 (select coalesce(sum(estimated_cost_usd),0) from public.ai_usage_events where created_at >= now()-interval '24 hours') as estimated_cost_24h;

create or replace view public.ai_governance_agent_performance with (security_invoker=true) as
select
 a.id as agent_id,a.agent_key,a.name,a.status,a.autonomy_level,
 count(distinct e.id) as executions_30d,
 count(distinct e.id) filter (where e.status='completed') as completed_30d,
 count(distinct e.id) filter (where e.status='failed') as failed_30d,
 count(distinct e.id) filter (where e.status='blocked') as blocked_30d,
 round(100.0 * count(distinct e.id) filter (where e.status='completed') / nullif(count(distinct e.id),0),2) as completion_rate_pct,
 coalesce(sum(u.total_tokens),0) as tokens_30d,
 coalesce(sum(u.estimated_cost_usd),0) as estimated_cost_30d
from public.ai_agent_registry a
left join public.ai_agent_executions e on e.agent_id=a.id and e.created_at >= now()-interval '30 days'
left join public.ai_usage_events u on u.created_at >= now()-interval '30 days'
where a.active=true
group by a.id,a.agent_key,a.name,a.status,a.autonomy_level;

