create or replace function public.assert_ai_agent_execution_transition(p_from text,p_to text)
returns boolean language plpgsql immutable as $$
begin
 if p_from=p_to then return true; end if;
 return case p_from
  when 'requested' then p_to in ('authorized','blocked','cancelled')
  when 'authorized' then p_to in ('prepared','blocked','cancelled','failed')
  when 'prepared' then p_to in ('running','blocked','cancelled','failed')
  when 'running' then p_to in ('awaiting_quality','awaiting_human_review','completed','blocked','failed','cancelled')
  when 'awaiting_quality' then p_to in ('awaiting_human_review','completed','blocked','failed','cancelled')
  when 'awaiting_human_review' then p_to in ('running','completed','blocked','failed','cancelled')
  when 'completed' then false
  when 'blocked' then false
  when 'failed' then false
  when 'cancelled' then false
  else false end;
end; $$;

create or replace function public.transition_ai_agent_execution(p_request_id uuid,p_status text,p_event_data jsonb default '{}'::jsonb)
returns jsonb language plpgsql security invoker set search_path='public' as $$
declare u uuid:=auth.uid(); role_name text; req public.ai_agent_execution_requests%rowtype; ex public.ai_agent_executions%rowtype;
begin
 select role into role_name from public.profiles where id=u and status='active';
 if role_name not in ('admin','staff','coach') then raise exception 'Authorized operations access required'; end if;
 select * into req from public.ai_agent_execution_requests where id=p_request_id for update;
 if not found then raise exception 'Execution request not found'; end if;
 if role_name='coach' and req.requested_by<>u then raise exception 'Coach may transition only own requests'; end if;
 if p_status not in ('running','awaiting_quality','awaiting_human_review','completed','blocked','failed','cancelled') then raise exception 'Invalid execution status'; end if;
 if not public.assert_ai_agent_execution_transition(req.status,p_status) then raise exception 'Invalid state transition from % to %',req.status,p_status; end if;
 if req.execution_id is not null then select * into ex from public.ai_agent_executions where id=req.execution_id; end if;
 update public.ai_agent_execution_requests set status=p_status,completed_at=case when p_status in ('completed','blocked','failed','cancelled') then now() else completed_at end,updated_at=now() where id=req.id;
 if ex.id is not null then update public.ai_agent_executions set status=p_status,error_message=case when p_status in ('failed','blocked') then coalesce(p_event_data->>'reason',error_message) else error_message end,updated_at=now() where id=ex.id; end if;
 insert into public.ai_agent_execution_events(request_id,execution_id,event_type,event_data,actor_id) values(req.id,req.execution_id,case when p_status='running' then 'started' when p_status='awaiting_quality' then 'quality_started' when p_status='awaiting_human_review' then 'human_review' when p_status='completed' then 'completed' when p_status='blocked' then 'blocked' when p_status='failed' then 'failed' else 'cancelled' end,coalesce(p_event_data,'{}'::jsonb),u);
 return jsonb_build_object('request_id',req.id,'execution_id',req.execution_id,'previous_status',req.status,'status',p_status);
end; $$;

