create or replace view public.ai_service_cost_margin_intelligence
with (security_invoker = true)
as
select
 s.id as service_id,
 s.name as service_name,
 s.currency as service_currency,
 coalesce(ec.price, s.price) as service_price,
 ec.human_delivery_hours,
 ec.human_cost_rate,
 ec.target_ai_cost_ceiling,
 ec.target_gross_margin_pct,
 coalesce(sum(a.ai_cost_usd),0)::numeric(14,6) as ai_cost_usd,
 coalesce(sum(a.input_tokens),0)::bigint as input_tokens,
 coalesce(sum(a.output_tokens),0)::bigint as output_tokens,
 coalesce(sum(a.total_tokens),0)::bigint as total_tokens,
 count(distinct a.delivery_run_id) as delivery_runs,
 case when ec.human_delivery_hours is not null and ec.human_cost_rate is not null then (ec.human_delivery_hours * ec.human_cost_rate)::numeric(14,2) else null end as human_delivery_cost,
 case when coalesce(ec.price,s.price) is not null and ec.human_delivery_hours is not null and ec.human_cost_rate is not null then (coalesce(ec.price,s.price) - coalesce(sum(a.ai_cost_usd),0) - (ec.human_delivery_hours * ec.human_cost_rate))::numeric(14,2) else null end as estimated_gross_profit,
 case when coalesce(ec.price,s.price) is not null and coalesce(ec.price,s.price) <> 0 and ec.human_delivery_hours is not null and ec.human_cost_rate is not null then round(((coalesce(ec.price,s.price) - coalesce(sum(a.ai_cost_usd),0) - (ec.human_delivery_hours * ec.human_cost_rate)) / coalesce(ec.price,s.price) * 100)::numeric,2) else null end as estimated_gross_margin_pct,
 case when ec.target_ai_cost_ceiling is not null and coalesce(sum(a.ai_cost_usd),0) > ec.target_ai_cost_ceiling then true else false end as ai_cost_ceiling_exceeded
from public.services s
left join public.service_unit_economics_config ec on ec.service_id=s.id and ec.active=true
left join public.ai_service_cost_allocations a on a.service_id=s.id
group by s.id,s.name,s.currency,s.price,ec.price,ec.human_delivery_hours,ec.human_cost_rate,ec.target_ai_cost_ceiling,ec.target_gross_margin_pct;

create or replace function public.allocate_ai_usage_to_service(p_usage_event_id uuid)
returns uuid
language plpgsql
security invoker
set search_path=public
as $$
declare v_event public.ai_usage_events%rowtype; v_delivery_id uuid; v_service_id uuid; v_alloc_id uuid;
begin
 if not exists (select 1 from public.profiles p where p.id=auth.uid() and p.status='active' and p.role=any(array['staff'::user_role,'admin'::user_role,'coach'::user_role])) then raise exception 'Not authorized'; end if;
 select * into v_event from public.ai_usage_events where id=p_usage_event_id;
 if not found then raise exception 'Usage event not found'; end if;
 select adr.id,adr.service_id into v_delivery_id,v_service_id
 from public.ai_service_delivery_runs adr
 join public.ai_service_workflow_executions awe on awe.delivery_run_id=adr.id
 where awe.id=v_event.run_id limit 1;
 if v_delivery_id is null then return null; end if;
 select id into v_alloc_id from public.ai_service_cost_allocations where usage_event_id=p_usage_event_id limit 1;
 if v_alloc_id is not null then return v_alloc_id; end if;
 insert into public.ai_service_cost_allocations(delivery_run_id,service_id,usage_event_id,ai_cost_usd,input_tokens,output_tokens,total_tokens,allocation_method,allocation_confidence,metadata)
 values(v_delivery_id,v_service_id,p_usage_event_id,coalesce(v_event.estimated_cost_usd,0),v_event.input_tokens,v_event.output_tokens,v_event.total_tokens,'direct_execution',1.0,jsonb_build_object('model',v_event.model_name,'provider',v_event.provider)) returning id into v_alloc_id;
 return v_alloc_id;
end; $$;

