create or replace view public.ai_cost_guardrail_status
with (security_invoker = true)
as
select
 g.id as guardrail_id,
 g.service_id,
 s.name as service_name,
 g.period_type,
 g.budget_usd,
 g.warning_pct,
 g.critical_pct,
 coalesce(sum(a.ai_cost_usd) filter (where
   (g.period_type = 'per_delivery') or
   (g.period_type = 'daily' and a.created_at >= date_trunc('day', now())) or
   (g.period_type = 'weekly' and a.created_at >= date_trunc('week', now())) or
   (g.period_type = 'monthly' and a.created_at >= date_trunc('month', now()))
 ),0)::numeric(14,6) as period_ai_cost_usd,
 case when g.budget_usd is not null and g.budget_usd > 0 then round((coalesce(sum(a.ai_cost_usd) filter (where
   (g.period_type = 'per_delivery') or
   (g.period_type = 'daily' and a.created_at >= date_trunc('day', now())) or
   (g.period_type = 'weekly' and a.created_at >= date_trunc('week', now())) or
   (g.period_type = 'monthly' and a.created_at >= date_trunc('month', now()))
 ),0) / g.budget_usd * 100)::numeric,2) else null end as budget_utilization_pct,
 case
   when g.budget_usd is null or g.budget_usd <= 0 then 'unconfigured'
   when coalesce(sum(a.ai_cost_usd) filter (where
     (g.period_type = 'per_delivery') or
     (g.period_type = 'daily' and a.created_at >= date_trunc('day', now())) or
     (g.period_type = 'weekly' and a.created_at >= date_trunc('week', now())) or
     (g.period_type = 'monthly' and a.created_at >= date_trunc('month', now()))
   ),0) / g.budget_usd * 100 >= g.critical_pct then 'critical'
   when coalesce(sum(a.ai_cost_usd) filter (where
     (g.period_type = 'per_delivery') or
     (g.period_type = 'daily' and a.created_at >= date_trunc('day', now())) or
     (g.period_type = 'weekly' and a.created_at >= date_trunc('week', now())) or
     (g.period_type = 'monthly' and a.created_at >= date_trunc('month', now()))
   ),0) / g.budget_usd * 100 >= g.warning_pct then 'warning'
   else 'within_budget'
 end as guardrail_status
from public.ai_cost_budget_guardrails g
join public.services s on s.id = g.service_id
left join public.ai_service_cost_allocations a on a.service_id = g.service_id
group by g.id,g.service_id,s.name,g.period_type,g.budget_usd,g.warning_pct,g.critical_pct;

