create policy "marketplace directory active profiles" on public.coach_marketplace_profiles for select to authenticated using(marketplace_status='active' or exists(select 1 from public.coaches c join public.profiles p on p.id=c.profile_id where c.id=coach_id and p.id=(select auth.uid())));
create policy "coach offerings readable" on public.coach_service_offerings for select to authenticated using(active=true or exists(select 1 from public.coaches c join public.profiles p on p.id=c.profile_id where c.id=coach_id and p.id=(select auth.uid())));
create policy "verification participants read" on public.coach_verification_records for select to authenticated using(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('admin','staff','coach')) or exists(select 1 from public.coaches c join public.profiles p on p.id=c.profile_id where c.id=coach_id and p.id=(select auth.uid())));
create policy "earnings owner staff read" on public.coach_earnings_ledger for select to authenticated using(exists(select 1 from public.coaches c join public.profiles p on p.id=c.profile_id where c.id=coach_id and p.id=(select auth.uid())) or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('admin','staff')));
create policy "booking participants read" on public.marketplace_booking_requests for select to authenticated using(exists(select 1 from public.clients cl join public.profiles p on p.id=cl.profile_id where cl.id=client_id and p.id=(select auth.uid())) or exists(select 1 from public.coaches c join public.profiles p on p.id=c.profile_id where c.id=coach_id and p.id=(select auth.uid())) or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('admin','staff')));
create policy "reviews readable" on public.marketplace_reviews for select to authenticated using(status='published' or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('admin','staff')) or exists(select 1 from public.clients cl join public.profiles p on p.id=cl.profile_id where cl.id=client_id and p.id=(select auth.uid())));
create policy "communications participants read" on public.marketplace_communications for select to authenticated using(exists(select 1 from public.clients cl join public.profiles p on p.id=cl.profile_id where cl.id=client_id and p.id=(select auth.uid())) or exists(select 1 from public.coaches c join public.profiles p on p.id=c.profile_id where c.id=coach_id and p.id=(select auth.uid())) or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('admin','staff')));
create policy "progress participants read" on public.client_marketplace_progress for select to authenticated using(exists(select 1 from public.clients cl join public.profiles p on p.id=cl.profile_id where cl.id=client_id and p.id=(select auth.uid())) or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('admin','staff')) or exists(select 1 from public.marketplace_booking_requests b join public.coaches c on c.id=b.coach_id join public.profiles p on p.id=c.profile_id where b.id=booking_id and p.id=(select auth.uid())));

create table if not exists public.coach_matching_preferences (
 id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, service_request_id uuid not null references public.service_requests(id) on delete cascade, preferred_coaching_formats text[] not null default '{}', preferred_languages text[] not null default '{}', preferred_countries text[] not null default '{}', preferred_timezones text[] not null default '{}', max_budget numeric, budget_currency text, minimum_rating numeric, minimum_years_coaching integer, credential_requirements text[] not null default '{}', specialization_requirements text[] not null default '{}', matching_notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(client_id, service_request_id));
create table if not exists public.coach_match_results (
 id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, service_request_id uuid not null references public.service_requests(id) on delete cascade, coach_id uuid not null references public.coaches(id) on delete cascade, score numeric not null default 0, rank integer, match_status text not null default 'candidate' check (match_status in ('candidate','recommended','shortlisted','selected','rejected','expired')), score_breakdown jsonb not null default '{}', match_reasons text[] not null default '{}', mismatch_flags text[] not null default '{}', ai_generated boolean not null default false, ai_model text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(service_request_id, coach_id));
create index if not exists idx_coach_match_results_request_score on public.coach_match_results(service_request_id, score desc);
create index if not exists idx_coach_match_results_coach on public.coach_match_results(coach_id);
create index if not exists idx_coach_matching_preferences_request on public.coach_matching_preferences(service_request_id);
alter table public.coach_matching_preferences enable row level security;
alter table public.coach_match_results enable row level security;
