grant select, insert, update on table public.coach_matching_preferences to authenticated;
grant select on table public.coach_match_results to authenticated;
create or replace view public.marketplace_coach_matching_candidates with (security_invoker=true) as
select c.id coach_id,cmp.id marketplace_profile_id,cmp.display_name,cmp.headline,cmp.bio,cmp.specializations,cmp.coaching_formats,cmp.languages,cmp.timezone,cmp.country,cmp.years_coaching,cmp.verification_status,cmp.marketplace_status,coalesce(avg(mr.rating),0) average_rating,count(mr.id)::integer review_count
from public.coaches c join public.coach_marketplace_profiles cmp on cmp.coach_id=c.id left join public.marketplace_reviews mr on mr.coach_id=c.id and mr.status='published'
where c.application_status='active' and cmp.verification_status='verified' and cmp.marketplace_status='active'
group by c.id,cmp.id;
create or replace function public.generate_coach_match_candidates(p_service_request_id uuid) returns jsonb language plpgsql security invoker set search_path=public as $$ declare v_client_id uuid; v_count integer:=0; begin select client_id into v_client_id from public.service_requests where id=p_service_request_id; if v_client_id is null then raise exception 'Service request not found'; end if; if not exists(select 1 from public.profiles p join public.clients c on c.profile_id=p.id where c.id=v_client_id and p.id=(select auth.uid())) and not exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('staff','admin')) then raise exception 'Not authorized'; end if; insert into public.coach_match_results(client_id,service_request_id,coach_id) select v_client_id,p_service_request_id,c.id from public.coaches c join public.coach_marketplace_profiles cmp on cmp.coach_id=c.id where c.application_status='active' and cmp.verification_status='verified' and cmp.marketplace_status='active' on conflict(service_request_id,coach_id) do nothing; get diagnostics v_count=row_count; return jsonb_build_object('service_request_id',p_service_request_id,'candidates_added',v_count); end; $$;
grant execute on function public.generate_coach_match_candidates(uuid) to authenticated;
create or replace function public.score_coach_match_candidates(p_service_request_id uuid) returns jsonb language plpgsql security invoker set search_path=public as $$ declare v_request public.service_requests%rowtype; v_pref public.coach_matching_preferences%rowtype; v_row record; v_score numeric; v_reasons text[]; v_flags text[]; v_total integer:=0; begin select * into v_request from public.service_requests where id=p_service_request_id; if v_request.id is null then raise exception 'Service request not found'; end if; if not exists(select 1 from public.profiles p join public.clients c on c.profile_id=p.id where c.id=v_request.client_id and p.id=(select auth.uid())) and not exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('staff','admin')) then raise exception 'Not authorized'; end if; select * into v_pref from public.coach_matching_preferences where service_request_id=p_service_request_id; for v_row in select r.id,r.coach_id,cmp.specializations,cmp.coaching_formats,cmp.languages,cmp.timezone,cmp.country,cmp.years_coaching,coalesce(avg(mr.rating),0) rating from public.coach_match_results r join public.coach_marketplace_profiles cmp on cmp.coach_id=r.coach_id left join public.marketplace_reviews mr on mr.coach_id=r.coach_id and mr.status='published' where r.service_request_id=p_service_request_id group by r.id,r.coach_id,cmp.specializations,cmp.coaching_formats,cmp.languages,cmp.timezone,cmp.country,cmp.years_coaching loop v_score:=0;v_reasons:='{}';v_flags:='{}'; if v_request.target_role is not null and exists(select 1 from unnest(v_row.specializations) s where lower(s) like '%'||lower(v_request.target_role)||'%') then v_score:=v_score+30;v_reasons:=array_append(v_reasons,'Specialization aligns with target role');end if; if v_pref.id is not null and cardinality(v_pref.specialization_requirements)>0 and v_row.specializations && v_pref.specialization_requirements then v_score:=v_score+25;v_reasons:=array_append(v_reasons,'Requested specialization match');end if; if v_pref.id is not null and cardinality(v_pref.preferred_languages)>0 and v_row.languages && v_pref.preferred_languages then v_score:=v_score+10;v_reasons:=array_append(v_reasons,'Language preference match');end if; if v_pref.id is not null and cardinality(v_pref.preferred_coaching_formats)>0 and v_row.coaching_formats && v_pref.preferred_coaching_formats then v_score:=v_score+10;v_reasons:=array_append(v_reasons,'Coaching format match');end if; if v_pref.id is not null and cardinality(v_pref.preferred_countries)>0 and v_row.country=any(v_pref.preferred_countries) then v_score:=v_score+5;v_reasons:=array_append(v_reasons,'Country preference match');end if; if v_pref.id is not null and cardinality(v_pref.preferred_timezones)>0 and v_row.timezone=any(v_pref.preferred_timezones) then v_score:=v_score+5;v_reasons:=array_append(v_reasons,'Timezone preference match');end if; if v_pref.id is not null and v_pref.minimum_years_coaching is not null and coalesce(v_row.years_coaching,0)<v_pref.minimum_years_coaching then v_flags:=array_append(v_flags,'Below requested coaching experience');end if; if v_pref.id is not null and v_pref.minimum_rating is not null and v_row.rating<v_pref.minimum_rating then v_flags:=array_append(v_flags,'Below requested rating');end if; v_score:=least(100,v_score+least(15,v_row.rating*3)); update public.coach_match_results set score=v_score,score_breakdown=jsonb_build_object('rating_bonus',least(15,v_row.rating*3),'reason_count',cardinality(v_reasons)),match_reasons=v_reasons,mismatch_flags=v_flags,updated_at=now() where id=v_row.id; end loop; update public.coach_match_results r set rank=x.rank,match_status=case when x.rank<=5 and cardinality(r.mismatch_flags)=0 then 'recommended' else 'candidate' end from(select id,row_number() over(order by score desc,id) rank from public.coach_match_results where service_request_id=p_service_request_id)x where r.id=x.id;select count(*) into v_total from public.coach_match_results where service_request_id=p_service_request_id;return jsonb_build_object('service_request_id',p_service_request_id,'scored_candidates',v_total);end; $$;
grant execute on function public.score_coach_match_candidates(uuid) to authenticated;

create table if not exists marketplace_booking_slots (
 id uuid primary key default gen_random_uuid(),
 coach_id uuid not null references coaches(id) on delete cascade,
 availability_id uuid references coach_availability(id) on delete set null,
 start_at timestamptz not null,
 end_at timestamptz not null,
 timezone text not null,
 status text not null default 'available' check (status in ('available','held','booked','blocked','cancelled')),
 booking_id uuid references marketplace_booking_requests(id) on delete set null,
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now(),
 constraint marketplace_booking_slots_time_ck check (end_at > start_at),
 constraint marketplace_booking_slots_booking_status_ck check ((status = 'booked' and booking_id is not null) or status <> 'booked')
);

create table if not exists marketplace_booking_events (
 id uuid primary key default gen_random_uuid(),
 booking_id uuid not null references marketplace_booking_requests(id) on delete cascade,
 event_type text not null check (event_type in ('requested','held','accepted','declined','confirmed','rescheduled','started','completed','cancelled','expired','no_show_client','no_show_coach','disputed')),
 actor_type text not null check (actor_type in ('client','coach','staff','admin','system','ai')),
 actor_id uuid,
 event_data jsonb not null default '{}'::jsonb,
 created_at timestamptz not null default now()
);

create index if not exists idx_marketplace_booking_slots_coach_time on marketplace_booking_slots(coach_id,start_at,end_at,status);
create index if not exists idx_marketplace_booking_slots_booking on marketplace_booking_slots(booking_id);
create index if not exists idx_marketplace_booking_events_booking on marketplace_booking_events(booking_id,created_at desc);

alter table marketplace_booking_slots enable row level security;
alter table marketplace_booking_events enable row level security;

create policy marketplace_booking_slots_coach_manage on marketplace_booking_slots for all to authenticated
using (exists (select 1 from coaches c join profiles p on p.id=c.profile_id where c.id=marketplace_booking_slots.coach_id and p.id=(select auth.uid())))
with check (exists (select 1 from coaches c join profiles p on p.id=c.profile_id where c.id=marketplace_booking_slots.coach_id and p.id=(select auth.uid())));

create policy marketplace_booking_slots_client_view on marketplace_booking_slots for select to authenticated
using (status='available' or exists (select 1 from marketplace_booking_requests b join clients cl on cl.id=b.client_id join profiles p on p.id=cl.profile_id where b.id=marketplace_booking_slots.booking_id and p.id=(select auth.uid())));

create policy marketplace_booking_slots_staff on marketplace_booking_slots for all to authenticated
using (exists (select 1 from profiles p where p.id=(select auth.uid()) and p.role in ('staff','admin')))
with check (exists (select 1 from profiles p where p.id=(select auth.uid()) and p.role in ('staff','admin')));

create policy marketplace_booking_events_participants on marketplace_booking_events for select to authenticated
using (exists (select 1 from marketplace_booking_requests b where b.id=marketplace_booking_events.booking_id and (exists (select 1 from clients cl join profiles p on p.id=cl.profile_id where cl.id=b.client_id and p.id=(select auth.uid())) or exists (select 1 from coaches c join profiles p on p.id=c.profile_id where c.id=b.coach_id and p.id=(select auth.uid())) or exists (select 1 from profiles p where p.id=(select auth.uid()) and p.role in ('staff','admin')))));

create or replace view marketplace_available_slots with (security_invoker=true) as
select s.id, s.coach_id, s.availability_id, s.start_at, s.end_at, s.timezone,
       o.id as coach_service_offering_id, o.service_id, o.title as service_title,
       o.price, o.currency, o.duration_minutes, o.delivery_mode
from marketplace_booking_slots s
join coach_service_offerings o on o.coach_id=s.coach_id and o.active=true
join coaches c on c.id=s.coach_id
where s.status='available' and c.application_status='active';

create or replace function create_marketplace_booking_request(
 p_client_id uuid, p_coach_id uuid, p_coach_service_offering_id uuid,
 p_service_request_id uuid, p_start_at timestamptz, p_end_at timestamptz,
 p_timezone text, p_client_notes text default null
) returns uuid language plpgsql security invoker as $$
declare v_id uuid; v_service_id uuid; v_duration integer;
begin
 if not exists (select 1 from clients cl join profiles p on p.id=cl.profile_id where cl.id=p_client_id and p.id=(select auth.uid())) then raise exception 'Unauthorized client'; end if;
 select service_id,duration_minutes into v_service_id,v_duration from coach_service_offerings where id=p_coach_service_offering_id and coach_id=p_coach_id and active=true;
 if v_service_id is null then raise exception 'Invalid service offering'; end if;
 if p_end_at <= p_start_at then raise exception 'Invalid booking interval'; end if;
 if not exists (select 1 from coaches where id=p_coach_id and application_status='active') then raise exception 'Coach is not active'; end if;
 if exists (select 1 from marketplace_booking_slots where coach_id=p_coach_id and status in ('held','booked') and tstzrange(start_at,end_at,'[)') && tstzrange(p_start_at,p_end_at,'[)')) then raise exception 'Requested time is unavailable'; end if;
 insert into marketplace_booking_requests(client_id,coach_id,service_id,coach_service_offering_id,service_request_id,requested_start,requested_end,timezone,booking_status,client_notes)
 values(p_client_id,p_coach_id,v_service_id,p_coach_service_offering_id,p_service_request_id,p_start_at,p_end_at,p_timezone,'requested',p_client_notes)
 returning id into v_id;
 insert into marketplace_booking_events(booking_id,event_type,actor_type,actor_id) values(v_id,'requested','client',(select auth.uid()));
 return v_id;
end $$;

grant execute on function create_marketplace_booking_request(uuid,uuid,uuid,uuid,timestamptz,timestamptz,text,text) to authenticated;

create or replace function coach_confirm_marketplace_booking(p_booking_id uuid, p_coach_notes text default null) returns boolean language plpgsql security invoker as $$
declare v_coach uuid; v_start timestamptz; v_end timestamptz; v_slot uuid;
begin
 select coach_id,requested_start,requested_end into v_coach,v_start,v_end from marketplace_booking_requests where id=p_booking_id;
 if not exists (select 1 from coaches c join profiles p on p.id=c.profile_id where c.id=v_coach and p.id=(select auth.uid())) then raise exception 'Unauthorized coach'; end if;
 if not exists (select 1 from marketplace_booking_requests where id=p_booking_id and booking_status='requested') then raise exception 'Booking is not awaiting confirmation'; end if;
 if exists (select 1 from marketplace_booking_slots where coach_id=v_coach and status in ('held','booked') and tstzrange(start_at,end_at,'[)') && tstzrange(v_start,v_end,'[)')) then raise exception 'Time slot already unavailable'; end if;
 insert into marketplace_booking_slots(coach_id,start_at,end_at,timezone,status,booking_id) select v_coach,v_start,v_end,timezone,'booked',p_booking_id from marketplace_booking_requests where id=p_booking_id returning id into v_slot;
 update marketplace_booking_requests set booking_status='confirmed',coach_notes=coalesce(p_coach_notes,coach_notes),updated_at=now() where id=p_booking_id;
 insert into marketplace_booking_events(booking_id,event_type,actor_type,actor_id) values(p_booking_id,'confirmed','coach',(select auth.uid()));
 return true;
end $$;

grant execute on function coach_confirm_marketplace_booking(uuid,text) to authenticated;

create or replace function cancel_marketplace_booking(p_booking_id uuid,p_reason text default null) returns boolean language plpgsql security invoker as $$
declare v_client uuid; v_coach uuid;
begin
 select client_id,coach_id into v_client,v_coach from marketplace_booking_requests where id=p_booking_id;
 if not (exists(select 1 from clients cl join profiles p on p.id=cl.profile_id where cl.id=v_client and p.id=(select auth.uid())) or exists(select 1 from coaches c join profiles p on p.id=c.profile_id where c.id=v_coach and p.id=(select auth.uid())) or exists(select 1 from profiles p where p.id=(select auth.uid()) and p.role in ('staff','admin'))) then raise exception 'Unauthorized'; end if;
 update marketplace_booking_requests set booking_status='cancelled',coach_notes=case when p_reason is not null then coalesce(coach_notes,'') || case when coach_notes is null or coach_notes='' then '' else E'\n' end || p_reason else coach_notes end,updated_at=now() where id=p_booking_id and booking_status not in ('completed','cancelled');
 update marketplace_booking_slots set status='cancelled',updated_at=now() where booking_id=p_booking_id and status in ('held','booked');
 insert into marketplace_booking_events(booking_id,event_type,actor_type,actor_id,event_data) values(p_booking_id,'cancelled',case when exists(select 1 from profiles p where p.id=(select auth.uid()) and p.role in ('staff','admin')) then 'staff' when exists(select 1 from clients cl join profiles p on p.id=cl.profile_id where cl.id=v_client and p.id=(select auth.uid())) then 'client' else 'coach' end,(select auth.uid()),jsonb_build_object('reason',p_reason));
 return true;
end $$;

grant execute on function cancel_marketplace_booking(uuid,text) to authenticated;

create table if not exists marketplace_transactions (
 id uuid primary key default gen_random_uuid(),
 booking_id uuid not null unique references marketplace_booking_requests(id) on delete restrict,
 client_id uuid not null references clients(id) on delete restrict,
 coach_id uuid not null references coaches(id) on delete restrict,
 service_id uuid not null references services(id) on delete restrict,
 currency text not null,
 gross_amount numeric(14,2) not null check (gross_amount >= 0),
 platform_share_pct numeric(5,2) not null check (platform_share_pct >= 0 and platform_share_pct <= 100),
 coach_share_pct numeric(5,2) not null check (coach_share_pct >= 0 and coach_share_pct <= 100),
 platform_fee numeric(14,2) not null default 0 check (platform_fee >= 0),
 coach_earnings numeric(14,2) not null default 0 check (coach_earnings >= 0),
 payment_status text not null default 'pending' check (payment_status in ('pending','authorized','funded','held','released','partially_refunded','refunded','failed','cancelled','disputed')),
 fulfillment_status text not null default 'not_started' check (fulfillment_status in ('not_started','in_progress','completed','accepted','disputed','cancelled')),
 release_eligibility text not null default 'blocked' check (release_eligibility in ('blocked','eligible','released')), 
 provider_key text,
 provider_transaction_reference text,
 provider_payment_reference text,
 metadata jsonb not null default '{}'::jsonb,
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now(),
 check (round(platform_fee + coach_earnings,2) = round(gross_amount,2)),
 check (round(platform_share_pct + coach_share_pct,2) = 100)
);

create table if not exists marketplace_transaction_events (
 id uuid primary key default gen_random_uuid(),
 transaction_id uuid not null references marketplace_transactions(id) on delete cascade,
 event_type text not null check (event_type in ('created','payment_pending','payment_authorized','funded','held','service_started','service_completed','client_accepted','release_eligible','released','refund_requested','refunded','partial_refund','payment_failed','cancelled','disputed','dispute_resolved','payout_pending','payout_completed','payout_failed')),
 actor_type text not null check (actor_type in ('client','coach','staff','admin','system','payment_provider')),
 actor_id uuid,
 provider_reference text,
 event_data jsonb not null default '{}'::jsonb,
 created_at timestamptz not null default now()
);

create table if not exists marketplace_refund_requests (
 id uuid primary key default gen_random_uuid(),
