create or replace function create_marketplace_transaction(p_booking_id uuid) returns uuid language plpgsql security invoker as $$
declare v_tx uuid; v_client uuid; v_coach uuid; v_service uuid; v_amount numeric; v_currency text; v_platform numeric; v_coach_share numeric; v_platform_fee numeric; v_coach_earnings numeric;
begin
 select b.client_id,b.coach_id,b.service_id,o.price,o.currency into v_client,v_coach,v_service,v_amount,v_currency from marketplace_booking_requests b join coach_service_offerings o on o.id=b.coach_service_offering_id and o.active=true where b.id=p_booking_id and b.booking_status='confirmed';
 if v_client is null then raise exception 'Confirmed booking/service offering not found'; end if;
 if not exists(select 1 from clients cl join profiles p on p.id=cl.profile_id where cl.id=v_client and p.id=(select auth.uid())) then raise exception 'Unauthorized'; end if;
 select platform_share_pct,coach_share_pct into v_platform,v_coach_share from platform_revenue_split_config where active=true and effective_from<=now() and (effective_to is null or effective_to>now()) order by effective_from desc limit 1;
 if v_platform is null then raise exception 'No active revenue split configuration'; end if;
 v_platform_fee=round(v_amount*v_platform/100,2); v_coach_earnings=round(v_amount-v_platform_fee,2);
 insert into marketplace_transactions(booking_id,client_id,coach_id,service_id,currency,gross_amount,platform_share_pct,coach_share_pct,platform_fee,coach_earnings)
 values(p_booking_id,v_client,v_coach,v_service,v_currency,v_amount,v_platform,v_coach_share,v_platform_fee,v_coach_earnings) returning id into v_tx;
 insert into marketplace_transaction_events(transaction_id,event_type,actor_type,actor_id,event_data) values(v_tx,'created','client',(select auth.uid()),jsonb_build_object('gross_amount',v_amount,'currency',v_currency,'platform_fee',v_platform_fee,'coach_earnings',v_coach_earnings));
 return v_tx;
end $$;
grant execute on function create_marketplace_transaction(uuid) to authenticated;

create or replace function mark_marketplace_service_completed(p_transaction_id uuid) returns boolean language plpgsql security invoker as $$
declare v_client uuid; v_coach uuid;
begin
 select client_id,coach_id into v_client,v_coach from marketplace_transactions where id=p_transaction_id;
 if not exists(select 1 from coaches c join profiles p on p.id=c.profile_id where c.id=v_coach and p.id=(select auth.uid())) then raise exception 'Unauthorized coach'; end if;
 update marketplace_transactions set fulfillment_status='completed',release_eligibility='eligible',updated_at=now() where id=p_transaction_id and payment_status in ('funded','held','authorized') and fulfillment_status not in ('cancelled','completed');
 if not found then raise exception 'Transaction is not eligible for completion'; end if;
 insert into marketplace_transaction_events(transaction_id,event_type,actor_type,actor_id) values(p_transaction_id,'service_completed','coach',(select auth.uid()));
 return true;
end $$;
grant execute on function mark_marketplace_service_completed(uuid) to authenticated;

create or replace function client_accept_marketplace_service(p_transaction_id uuid) returns boolean language plpgsql security invoker as $$
declare v_client uuid;
begin
 select client_id into v_client from marketplace_transactions where id=p_transaction_id;
 if not exists(select 1 from clients cl join profiles p on p.id=cl.profile_id where cl.id=v_client and p.id=(select auth.uid())) then raise exception 'Unauthorized client'; end if;
 update marketplace_transactions set fulfillment_status='accepted',release_eligibility=case when payment_status in ('funded','held') then 'eligible' else release_eligibility end,updated_at=now() where id=p_transaction_id and fulfillment_status='completed';
 if not found then raise exception 'Service is not awaiting acceptance'; end if;
 insert into marketplace_transaction_events(transaction_id,event_type,actor_type,actor_id) values(p_transaction_id,'client_accepted','client',(select auth.uid()));
 return true;
end $$;
grant execute on function client_accept_marketplace_service(uuid) to authenticated;

