create or replace function public.marketplace_communication_risk_classify(p_body text) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$ declare s text := lower(coalesce(p_body,'')); score numeric := 0; ext_contact boolean := false; ext_business boolean := false; reasons jsonb := '[]'::jsonb; begin if s ~ '(https?://|www\.)' then score := score + 25; reasons := reasons || jsonb_build_array('external_url'); end if; if s ~ '([a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,})' then score := score + 35; ext_contact := true; reasons := reasons || jsonb_build_array('email_address'); end if; if s ~ '(\+?[0-9][0-9 .()\-]{7,}[0-9])' then score := score + 30; ext_contact := true; reasons := reasons || jsonb_build_array('phone_number'); end if; if s ~ '(pay me directly|pay outside|outside the platform|off platform|whatsapp me|telegram me|contact me directly|let us continue privately|bank transfer|cashapp|venmo|paypal me|send payment)' then score := score + 45; ext_business := true; reasons := reasons || jsonb_build_array('off_platform_solicitation'); end if; if score > 100 then score := 100; end if; return jsonb_build_object('risk_score',score,'external_contact_detected',ext_contact,'external_business_intent_detected',ext_business,'reasons',reasons,'policy_action',case when score >= 80 then 'block' when score >= 60 then 'review' when score >= 35 then 'flag' when score >= 20 then 'warn' else 'allow' end); end $$;
create or replace function public.send_marketplace_communication(p_booking_id uuid,p_body text,p_message_type text default 'text') returns uuid language plpgsql security invoker set search_path=public,pg_temp as $$ declare b public.marketplace_booking_requests%rowtype; c public.marketplace_communications%rowtype; r jsonb; sender text; uid uuid := auth.uid(); begin if uid is null then raise exception 'Authentication required'; end if; select * into b from public.marketplace_booking_requests where id=p_booking_id; if not found then raise exception 'Booking not found'; end if; if exists(select 1 from public.clients x where x.id=b.client_id and x.profile_id=uid) then sender := 'client'; elsif exists(select 1 from public.coaches x where x.id=b.coach_id and x.profile_id=uid) then sender := 'coach'; else raise exception 'Not a participant in this booking'; end if; r := public.marketplace_communication_risk_classify(p_body); insert into public.marketplace_communications(booking_id,client_id,coach_id,sender_role,message_type,body,moderation_status,external_contact_detected,external_business_intent_detected,risk_score,policy_action,moderation_reason) values(p_booking_id,b.client_id,b.coach_id,sender,p_message_type,p_body,case when (r->>'policy_action')='block' then 'blocked' when (r->>'policy_action') in ('review','flag') then 'flagged' else 'allowed' end,(r->>'external_contact_detected')::boolean,(r->>'external_business_intent_detected')::boolean,(r->>'risk_score')::numeric,(r->>'policy_action'),array_to_string(array(select jsonb_array_elements_text(r->'reasons')) ,', ')) returning * into c; insert into public.marketplace_communication_events(communication_id,event_type,actor_type,actor_id,event_data) values(c.id,case when c.moderation_status='blocked' then 'blocked' when c.moderation_status='flagged' then 'flagged' when c.policy_action='warn' then 'warning_issued' else 'sent' end,sender,uid,r); if c.moderation_status in ('blocked','flagged') then insert into public.marketplace_communication_risk_flags(communication_id,risk_type,risk_score,detected_by,evidence) values(c.id,case when (r->>'external_business_intent_detected')::boolean then 'off_platform_business' when (r->>'external_contact_detected')::boolean then 'external_contact' else 'other' end,(r->>'risk_score')::numeric,'rule',r); end if; return c.id; end $$;
revoke all on function public.marketplace_communication_risk_classify(text) from public,anon,authenticated;
grant execute on function public.marketplace_communication_risk_classify(text) to authenticated;
