create or replace function public.update_client_marketplace_preferences(p_preferred_coach_id uuid default null) returns void language plpgsql security invoker set search_path=public,pg_temp as $$ declare uid uuid:=auth.uid(); cid uuid; begin if uid is null then raise exception 'Authentication required'; end if; select id into cid from public.clients where profile_id=uid; if cid is null then raise exception 'Client profile not found'; end if; if p_preferred_coach_id is not null and not exists(select 1 from public.coaches co join public.coach_marketplace_profiles mp on mp.coach_id=co.id where co.id=p_preferred_coach_id and co.application_status='active' and mp.marketplace_status='active') then raise exception 'Selected coach is not active on the marketplace'; end if; update public.clients set preferred_coach_id=p_preferred_coach_id,updated_at=now() where id=cid; end $$;
