create or replace function public.schedule_marketplace_booking_reminders(p_booking_id uuid)
returns integer language plpgsql security invoker set search_path=public as $$
declare b record; v_count integer:=0; v_start timestamptz; v_key text;
begin
  select * into b from public.marketplace_booking_requests where id=p_booking_id;
  if not found then raise exception 'booking not found'; end if;
  if b.booking_status not in ('requested','confirmed') then return 0; end if;
  v_start:=b.requested_start;
  if v_start is null then return 0; end if;
  if v_start > now() + interval '24 hours' then
    v_key:=p_booking_id::text||':session_24h';
    insert into public.marketplace_notification_schedules(booking_id,client_id,coach_id,reminder_type,scheduled_for,dedupe_key,metadata)
    values(p_booking_id,b.client_id,b.coach_id,'session_24h',v_start-interval '24 hours',v_key,jsonb_build_object('timezone',b.timezone)) on conflict(dedupe_key) do nothing;
    v_count:=v_count+1;
  end if;
  if v_start > now() + interval '1 hour' then
    v_key:=p_booking_id::text||':session_1h';
    insert into public.marketplace_notification_schedules(booking_id,client_id,coach_id,reminder_type,scheduled_for,dedupe_key,metadata)
    values(p_booking_id,b.client_id,b.coach_id,'session_1h',v_start-interval '1 hour',v_key,jsonb_build_object('timezone',b.timezone)) on conflict(dedupe_key) do nothing;
    v_count:=v_count+1;
  end if;
  v_key:=p_booking_id::text||':session_start';
  insert into public.marketplace_notification_schedules(booking_id,client_id,coach_id,reminder_type,scheduled_for,dedupe_key,metadata)
  values(p_booking_id,b.client_id,b.coach_id,'session_start',v_start,v_key,jsonb_build_object('timezone',b.timezone)) on conflict(dedupe_key) do nothing;
  v_count:=v_count+1;
  return v_count;
end; $$;

create or replace function public.process_due_marketplace_reminders(p_limit integer default 100)
returns integer language plpgsql security invoker set search_path=public as $$
declare r record; run_id uuid; n integer:=0; v_profile uuid; v_type text; v_title text; v_body text; v_notification uuid;
begin
  insert into public.marketplace_reminder_runs default values returning id into run_id;
  for r in select s.*,b.service_id,coalesce(o.title,'coaching session') as service_name,coalesce(mp.display_name,cprofile.full_name,'Coach') as coach_name,coalesce(cp.full_name,'Client') as client_name from public.marketplace_notification_schedules s join public.marketplace_booking_requests b on b.id=s.booking_id left join public.coach_service_offerings o on o.id=b.coach_service_offering_id left join public.coach_marketplace_profiles mp on mp.coach_id=b.coach_id left join public.profiles cprofile on cprofile.id=(select profile_id from public.coaches where id=b.coach_id) left join public.clients cl on cl.id=b.client_id left join public.profiles cp on cp.id=cl.profile_id where s.status='scheduled' and s.scheduled_for<=now() and b.booking_status='confirmed' order by s.scheduled_for for update of s skip locked limit greatest(p_limit,1) loop
    update public.marketplace_notification_schedules set status='queued',updated_at=now() where id=r.id;
    for v_profile,v_type in select * from (values ((select profile_id from public.clients where id=r.client_id),'client'),((select profile_id from public.coaches where id=r.coach_id),'coach')) x(profile_id,role) loop
      if r.reminder_type='session_24h' then v_title:='Session reminder: 24 hours'; v_body:='Your session for '||r.service_name||' is scheduled for tomorrow.';
      elsif r.reminder_type='session_1h' then v_title:='Session reminder: 1 hour'; v_body:='Your '||r.service_name||' session starts in about one hour.';
      else v_title:='Your coaching session starts'; v_body:='Your '||r.service_name||' session is scheduled to start now.'; end if;
      v_notification:=public.create_marketplace_event_notification(v_profile,r.client_id,r.coach_id,r.booking_id,null,'session_reminder','booking','high',v_title,v_body,case when v_type='client' then '/client/bookings' else '/coach/bookings' end,now(),jsonb_build_object('reminder_type',r.reminder_type,'scheduled_for',r.scheduled_for),'session_reminders');
      if v_notification is not null then update public.marketplace_notification_schedules set notification_id=v_notification,status='sent',updated_at=now() where id=r.id; else update public.marketplace_notification_schedules set status='skipped',updated_at=now() where id=r.id; end if;
    end loop;
    n:=n+1;
  end loop;
  update public.marketplace_reminder_runs set run_finished_at=now(),scanned_count=n,queued_count=n,status='completed' where id=run_id;
  return n;
exception when others then
  update public.marketplace_reminder_runs set run_finished_at=now(),status='failed',error_message=sqlerrm where id=run_id;
  raise;
end; $$;

