create or replace function public.validate_marketplace_financial_ledger(p_transaction_id uuid)
returns jsonb
language plpgsql
security invoker
set search_path=public
as $$
declare t public.marketplace_transactions%rowtype; refund_total numeric; payout_total numeric; result jsonb;
begin
 if (select auth.uid()) is null then raise exception 'Authentication required'; end if;
 if not exists (select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('staff','admin')) then raise exception 'Staff or admin access required'; end if;
 select * into t from public.marketplace_transactions where id=p_transaction_id;
 if not found then raise exception 'Marketplace transaction not found'; end if;
 select coalesce(sum(amount),0) into refund_total from public.marketplace_refunds where transaction_id=t.id and status in ('approved','processing','completed','partially_completed');
 select coalesce(sum(payout_amount),0) into payout_total from public.marketplace_payouts where transaction_id=t.id and status in ('processing','paid','eligible');
 result=jsonb_build_object(
  'transaction_id',t.id,
  'gross_amount',t.gross_amount,
  'platform_share_pct',t.platform_share_pct,
  'coach_share_pct',t.coach_share_pct,
  'platform_fee',t.platform_fee,
  'coach_earnings',t.coach_earnings,
  'refund_total',refund_total,
  'payout_total',payout_total,
  'split_valid',abs((t.platform_share_pct+t.coach_share_pct)-100) < 0.000001 and abs((t.platform_fee+t.coach_earnings)-t.gross_amount) < 0.000001,
  'refunds_valid',refund_total <= t.gross_amount,
  'payouts_valid',payout_total <= t.coach_earnings,
  'ledger_balanced',abs((t.platform_fee+t.coach_earnings+t.gross_amount*0)-t.gross_amount) < 0.000001
 );
 return result;
end; $$;

revoke all on function public.validate_marketplace_financial_ledger(uuid) from public,anon,authenticated;
grant execute on function public.validate_marketplace_financial_ledger(uuid) to authenticated;

create or replace view public.marketplace_financial_ledger_integrity with (security_invoker=true) as
select t.id as transaction_id,t.currency,t.gross_amount,t.platform_share_pct,t.coach_share_pct,t.platform_fee,t.coach_earnings,
 coalesce(r.refund_total,0) refund_total,coalesce(p.payout_total,0) payout_total,
 (abs((t.platform_share_pct+t.coach_share_pct)-100)<0.000001 and abs((t.platform_fee+t.coach_earnings)-t.gross_amount)<0.000001) as split_integrity,
 (coalesce(r.refund_total,0)<=t.gross_amount) as refund_integrity,
 (coalesce(p.payout_total,0)<=t.coach_earnings) as payout_integrity,
 (coalesce(l.entry_count,0)>0) as ledger_entries_present
from public.marketplace_transactions t
left join (select transaction_id,sum(amount) refund_total from public.marketplace_refunds where status in ('approved','processing','completed','partially_completed') group by transaction_id) r on r.transaction_id=t.id
left join (select transaction_id,sum(payout_amount) payout_total from public.marketplace_payouts where status in ('processing','paid','eligible') group by transaction_id) p on p.transaction_id=t.id
left join (select transaction_id,count(*) entry_count from public.marketplace_ledger_entries group by transaction_id) l on l.transaction_id=t.id;

grant select on public.marketplace_financial_ledger_integrity to authenticated;

