create or replace view public.marketplace_financial_operations_by_currency with (security_invoker=true) as select currency,count(*) as transaction_count,coalesce(sum(gross_amount),0) as gross_value,coalesce(sum(platform_fee),0) as platform_revenue,coalesce(sum(coach_earnings),0) as coach_entitlements from public.marketplace_transactions group by currency order by currency;
create or replace view public.marketplace_financial_operations_exceptions with (security_invoker=true) as select id,transaction_id,payout_id,refund_id,exception_type,severity,status,description,detected_by,created_at,updated_at from public.marketplace_financial_audit_exceptions where status in ('open','under_review') order by case severity when 'critical' then 1 when 'high' then 2 when 'medium' then 3 else 4 end,created_at desc;

