create or replace function public.admin_review_coach_application(p_application_id uuid, p_decision text, p_notes text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_role text;
  a public.coach_marketplace_applications%rowtype;
  v_coach_id uuid;
  v_profile_id uuid;
begin
  select role into v_role from public.profiles where id = auth.uid();
  if v_role not in ('admin','super_admin','coach_admin','platform_admin') then
    raise exception 'not authorized';
  end if;
  if p_decision not in ('approve','reject') then
    raise exception 'decision must be approve or reject';
  end if;

  select * into a from public.coach_marketplace_applications where id = p_application_id for update;
  if not found then raise exception 'application not found'; end if;

  if p_decision = 'reject' then
    update public.coach_marketplace_applications
      set application_status='rejected', reviewed_at=now(), reviewer_id=auth.uid(), review_notes=p_notes
      where id=p_application_id;
    return jsonb_build_object('status','rejected','application_id',p_application_id);
  end if;

  if not a.required_agreements_accepted then
    raise exception 'required agreements must be accepted before approval';
  end if;
  if coalesce(array_length(a.specializations,1),0)=0 then raise exception 'at least one specialization is required'; end if;
  if coalesce(array_length(a.coaching_formats,1),0)=0 then raise exception 'at least one coaching format is required'; end if;
  if coalesce(a.display_name,'')='' or coalesce(a.professional_title,'')='' then raise exception 'display name and professional title are required'; end if;

  insert into public.profiles (id)
    values (a.applicant_user_id)
    on conflict (id) do nothing;

  insert into public.coaches (
    profile_id, professional_title, professional_bio, years_experience,
    coaching_experience_years, methodology, languages, credentials,
    linkedin_url, website_url, availability_summary, timezone,
    application_status, verified_at, approved_at
  ) values (
    a.applicant_user_id, a.professional_title, coalesce(a.professional_bio,a.bio),
    a.years_experience, a.coaching_experience_years, a.methodology, a.languages,
    a.credentials, a.linkedin_url, a.website_url, a.availability_summary, a.timezone,
    'approved', now(), now()
  )
  on conflict (profile_id) do update set
    professional_title=excluded.professional_title,
    professional_bio=excluded.professional_bio,
    years_experience=excluded.years_experience,
    coaching_experience_years=excluded.coaching_experience_years,
    methodology=excluded.methodology,
    languages=excluded.languages,
    credentials=excluded.credentials,
    linkedin_url=excluded.linkedin_url,
    website_url=excluded.website_url,
    availability_summary=excluded.availability_summary,
    timezone=excluded.timezone,
    application_status='approved', verified_at=now(), approved_at=now(), updated_at=now()
  returning id into v_coach_id;

  insert into public.coach_marketplace_profiles (
    coach_id, display_name, headline, bio, specializations, coaching_formats,
    languages, timezone, country, years_coaching, verification_status,
    marketplace_status, profile_completion_pct
  ) values (
    v_coach_id, a.display_name, a.headline, a.bio, a.specializations, a.coaching_formats,
    a.languages, a.timezone, a.country, a.coaching_experience_years, 'verified',
    'pending_activation', 85
  )
  on conflict (coach_id) do update set
    display_name=excluded.display_name, headline=excluded.headline, bio=excluded.bio,
    specializations=excluded.specializations, coaching_formats=excluded.coaching_formats,
    languages=excluded.languages, timezone=excluded.timezone, country=excluded.country,
    years_coaching=excluded.years_coaching, verification_status='verified',
    marketplace_status='pending_activation', profile_completion_pct=greatest(public.coach_marketplace_profiles.profile_completion_pct,85), updated_at=now()
  returning id into v_profile_id;

  insert into public.coach_marketplace_onboarding (coach_id,onboarding_status,required_agreements_accepted,agreements_accepted_at,submitted_at,eligibility_checked_at,eligible_for_activation,activation_blockers,last_reviewed_by,last_reviewed_at,notes)
  values (v_coach_id,'approved',true,a.agreements_accepted_at,a.created_at,now(),false,jsonb_build_array('availability_required'),auth.uid(),now(),p_notes)
  on conflict (coach_id) do update set
    onboarding_status='approved', required_agreements_accepted=true, agreements_accepted_at=a.agreements_accepted_at,
    submitted_at=coalesce(public.coach_marketplace_onboarding.submitted_at,a.created_at), eligibility_checked_at=now(),
    eligible_for_activation=false, activation_blockers=jsonb_build_array('availability_required'), last_reviewed_by=auth.uid(), last_reviewed_at=now(), notes=p_notes, updated_at=now();

  update public.coach_marketplace_applications
    set application_status='approved', reviewed_at=now(), reviewer_id=auth.uid(), review_notes=p_notes
    where id=p_application_id;

  return jsonb_build_object('status','approved','application_id',p_application_id,'coach_id',v_coach_id,'marketplace_profile_id',v_profile_id,'next_step','availability_and_activation');
end;
$$;

