create or replace function public.admin_activate_coach(p_coach_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
 v_role text; v_blockers jsonb := '[]'::jsonb; v_profile public.coach_marketplace_profiles%rowtype; v_onboarding public.coach_marketplace_onboarding%rowtype; v_availability_count integer;
begin
 select role into v_role from public.profiles where id=auth.uid();
 if v_role not in ('admin','super_admin','coach_admin','platform_admin') then raise exception 'not authorized'; end if;
 select * into v_profile from public.coach_marketplace_profiles where coach_id=p_coach_id for update;
 if not found then raise exception 'marketplace profile not found'; end if;
 select * into v_onboarding from public.coach_marketplace_onboarding where coach_id=p_coach_id;
 if not found then raise exception 'onboarding record not found'; end if;
 select count(*) into v_availability_count from public.coach_marketplace_availability where coach_id=p_coach_id and active=true;
 if v_profile.verification_status <> 'verified' then v_blockers := v_blockers || jsonb_build_array('verification_required'); end if;
 if v_onboarding.required_agreements_accepted is not true then v_blockers := v_blockers || jsonb_build_array('agreements_required'); end if;
 if v_availability_count = 0 then v_blockers := v_blockers || jsonb_build_array('availability_required'); end if;
 if jsonb_array_length(v_blockers)>0 then
   update public.coach_marketplace_onboarding set eligible_for_activation=false, activation_blockers=v_blockers, eligibility_checked_at=now(), last_reviewed_by=auth.uid(), last_reviewed_at=now(), updated_at=now() where coach_id=p_coach_id;
   return jsonb_build_object('activated',false,'coach_id',p_coach_id,'blockers',v_blockers);
 end if;
 update public.coach_marketplace_onboarding set eligible_for_activation=true, activation_blockers='[]'::jsonb, eligibility_checked_at=now(), last_reviewed_by=auth.uid(), last_reviewed_at=now(), updated_at=now() where coach_id=p_coach_id;
 update public.coach_marketplace_profiles set marketplace_status='active', updated_at=now() where coach_id=p_coach_id;
 return jsonb_build_object('activated',true,'coach_id',p_coach_id,'blockers','[]'::jsonb);
end;
$$;
