create or replace function public.create_marketplace_booking_request(
  p_client_id uuid,
  p_coach_id uuid,
  p_coach_service_offering_id uuid,
  p_service_request_id uuid,
  p_start_at timestamptz,
  p_end_at timestamptz,
  p_timezone text,
  p_client_notes text default null
)
returns uuid
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_id uuid;
  v_service_id uuid;
  v_duration integer;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  if not exists (
    select 1
    from clients cl
    join profiles p on p.id = cl.profile_id
    where cl.id = p_client_id
      and p.id = auth.uid()
  ) then
    raise exception 'Unauthorized client';
  end if;

  select service_id, duration_minutes
    into v_service_id, v_duration
  from coach_service_offerings
  where id = p_coach_service_offering_id
    and coach_id = p_coach_id
    and active = true;

  if v_service_id is null then
    raise exception 'Invalid service offering';
  end if;

  if p_start_at is null or p_end_at is null or p_end_at <= p_start_at then
    raise exception 'Invalid booking interval';
  end if;

  if extract(epoch from (p_end_at - p_start_at))/60 <> v_duration then
    raise exception 'Booking duration must match the selected service offering';
  end if;

  if not exists (
    select 1
    from coaches
    where id = p_coach_id
      and application_status in ('approved','active')
  ) then
    raise exception 'Coach is not approved for marketplace booking';
  end if;

  if exists (
    select 1
    from marketplace_booking_slots
    where coach_id = p_coach_id
      and status in ('held','booked')
      and tstzrange(start_at, end_at, '[)') && tstzrange(p_start_at, p_end_at, '[)')
  ) then
    raise exception 'Requested time is unavailable';
  end if;

  insert into marketplace_booking_requests (
    client_id, coach_id, service_id, coach_service_offering_id,
    service_request_id, requested_start, requested_end, timezone,
    booking_status, client_notes
  )
  values (
    p_client_id, p_coach_id, v_service_id, p_coach_service_offering_id,
    p_service_request_id, p_start_at, p_end_at, p_timezone,
    'requested', p_client_notes
  )
  returning id into v_id;

  insert into marketplace_booking_events (
    booking_id, event_type, actor_type, actor_id, event_data
  )
  values (
    v_id, 'requested', 'client', auth.uid(),
    jsonb_build_object('timezone', p_timezone)
  );

  return v_id;
end;
$$;

