CREATE OR REPLACE FUNCTION public.prepare_ai_agent_execution(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  u uuid:=auth.uid();
  role_name text;
  r public.ai_agent_execution_requests%rowtype;
  agent_row public.ai_agent_registry%rowtype;
  e uuid;
  snapshot_count integer;
begin
  select role into role_name from public.profiles where id=u and status='active';
  if role_name not in ('admin','staff','coach') then
    raise exception 'Authorized service team access required';
  end if;

  select * into r from public.ai_agent_execution_requests where id=p_request_id for update;
  if not found then raise exception 'Execution request not found'; end if;
  if role_name='coach' and r.requested_by<>u then raise exception 'Coach may only prepare own requests'; end if;
  if r.status not in ('authorized','prepared') then raise exception 'Request is not ready for preparation'; end if;

  if r.execution_id is null then
    insert into public.ai_agent_executions(
      agent_id,workflow_id,status,trigger_source,input_snapshot,
      human_review_required,human_review_status,created_by
    )
    select r.agent_id,r.workflow_id,'authorized',r.trigger_source,r.input_payload,
      agent_row.human_approval_required,
      case when agent_row.human_approval_required then 'pending' else 'not_required' end,
      u
    from public.ai_agent_registry as agent_row
    where agent_row.id=r.agent_id
    returning id into e;

    update public.ai_agent_execution_requests
      set execution_id=e,status='prepared'
      where id=r.id;
  else
    e:=r.execution_id;
    update public.ai_agent_execution_requests set status='prepared' where id=r.id;
  end if;

  select public.capture_ai_agent_configuration_snapshot(e) into snapshot_count;

  insert into public.ai_agent_execution_events(
    request_id,execution_id,event_type,event_data,actor_id
  )
  values(
    r.id,e,'configuration_captured',
    jsonb_build_object('snapshot_count',snapshot_count),u
  );

  return jsonb_build_object(
    'request_id',r.id,'execution_id',e,
    'snapshot_count',snapshot_count,'status','prepared'
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.prepare_ai_agent_execution(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  u uuid:=auth.uid();
  role_name text;
  r public.ai_agent_execution_requests%rowtype;
  approval_required boolean;
  e uuid;
  snapshot_count integer;
begin
  select role into role_name from public.profiles where id=u and status='active';
  if role_name not in ('admin','staff','coach') then
    raise exception 'Authorized service team access required';
  end if;
  select * into r from public.ai_agent_execution_requests where id=p_request_id for update;
  if not found then raise exception 'Execution request not found'; end if;
  if role_name='coach' and r.requested_by<>u then raise exception 'Coach may only prepare own requests'; end if;
  if r.status not in ('authorized','prepared') then raise exception 'Request is not ready for preparation'; end if;

  select ar.human_approval_required into approval_required
  from public.ai_agent_registry ar
  where ar.id=r.agent_id;

  if r.execution_id is null then
    insert into public.ai_agent_executions(
      agent_id,workflow_id,status,trigger_source,input_snapshot,
      human_review_required,human_review_status,created_by
    )
    values(
      r.agent_id,r.workflow_id,'authorized',r.trigger_source,r.input_payload,
      approval_required,
      case when approval_required then 'pending' else 'not_required' end,
      u
    )
    returning id into e;
    update public.ai_agent_execution_requests set execution_id=e,status='prepared' where id=r.id;
  else
    e:=r.execution_id;
    update public.ai_agent_execution_requests set status='prepared' where id=r.id;
  end if;

  select public.capture_ai_agent_configuration_snapshot(e) into snapshot_count;
  insert into public.ai_agent_execution_events(request_id,execution_id,event_type,event_data,actor_id)
  values(r.id,e,'configuration_captured',jsonb_build_object('snapshot_count',snapshot_count),u);

  return jsonb_build_object('request_id',r.id,'execution_id',e,'snapshot_count',snapshot_count,'status','prepared');
end;
$function$;

CREATE OR REPLACE FUNCTION public.transition_ai_agent_execution(p_request_id uuid, p_status text, p_event_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  u uuid:=auth.uid();
  role_name text;
  req public.ai_agent_execution_requests%rowtype;
  ex public.ai_agent_executions%rowtype;
begin
