language plpgsql
set search_path=public
as $$
declare
  u uuid:=auth.uid(); role_name text; req public.ai_agent_execution_requests%rowtype; ex public.ai_agent_executions%rowtype; execution_status text;
begin
  select role into role_name from public.profiles where id=u and status='active';
