  update public.ai_agent_execution_requests set status=p_status,
    completed_at=case when p_status in ('completed','blocked','failed','cancelled') then now() else completed_at end
    where id=req.id;
  if ex.id is not null then
    update public.ai_agent_executions set status=execution_status,
      error_message=case when p_status in ('failed','blocked') then coalesce(p_event_data->>'reason',error_message) else error_message end,
      updated_at=now() where id=ex.id;
  end if;

  insert into public.ai_agent_execution_events(request_id,execution_id,event_type,event_data,actor_id)
