    case when p_status='running' then 'started' when p_status='awaiting_quality' then 'quality_started'
         when p_status='awaiting_human_review' then 'human_review' when p_status='completed' then 'completed'
         when p_status='blocked' then 'blocked' when p_status='failed' then 'failed' else 'cancelled' end,
