create or replace function public.reserve_ai_credits(
  p_operation_key text,
  p_execution_id uuid default null,
  p_request_id uuid default null,
  p_idempotency_key text default null,
  p_metadata jsonb default '{}'::jsonb
)
returns table (
  allowed boolean,
  reason text,
  ledger_id uuid,
  credits_required integer,
  credits_remaining integer,
  monthly_allowance integer,
  credits_consumed integer,
  credits_reserved integer,
  period_start timestamptz,
  period_end timestamptz,
  plan_key text
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := (select auth.uid());
  v_role text;
  v_sub public.ai_agent_subscriptions%rowtype;
  v_plan public.ai_agent_subscription_plans%rowtype;
  v_op public.ai_credit_operations%rowtype;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_consumed integer := 0;
  v_reserved integer := 0;
  v_existing public.ai_credit_ledger%rowtype;
  v_ledger_id uuid;
  v_key text;
begin
  if v_user_id is null then
    raise exception 'Authentication required';
  end if;

  select p.role into v_role from public.profiles p where p.id = v_user_id;
  if v_role in ('admin','staff') then
    return query select true,'internal_staff_usage_no_customer_credit',null::uuid,0,0,0,0,0,now(),now(),null::text;
    return;
  end if;

  select * into v_op from public.ai_credit_operations where operation_key=p_operation_key and active=true;
  if not found then
    raise exception 'Unknown or inactive AI credit operation: %', p_operation_key;
  end if;

  v_key := coalesce(nullif(trim(p_idempotency_key),''),coalesce(p_execution_id::text,p_request_id::text,p_operation_key||':'||clock_timestamp()::text));

  select * into v_existing
  from public.ai_credit_ledger
  where user_id=v_user_id and idempotency_key=v_key
  limit 1;

  if found then
    select coalesce(sum(case when status='consumed' then credits else 0 end),0),
           coalesce(sum(case when status='reserved' then credits else 0 end),0)
      into v_consumed,v_reserved
    from public.ai_credit_ledger
    where user_id=v_user_id and period_start=v_existing.period_start and period_end=v_existing.period_end;
    select monthly_credits into v_plan.monthly_credits
      from public.ai_agent_subscription_plans where plan_key=v_existing.plan_key;
    return query select
      true,'idempotent_existing_request',v_existing.id,v_existing.credits,
      greatest(v_plan.monthly_credits-v_consumed-v_reserved,0),
      v_plan.monthly_credits,v_consumed,v_reserved,v_existing.period_start,v_existing.period_end,v_existing.plan_key;
    return;
  end if;

  select * into v_sub
  from public.ai_agent_subscriptions s
  where s.user_id=v_user_id and s.status in ('active','non_renewing')
  order by s.updated_at desc
  limit 1
  for update;

  if not found then
    return query select false,'no_active_ai_subscription',null::uuid,0,0,0,0,0,now(),now(),null::text;
    return;
  end if;

  select * into v_plan from public.ai_agent_subscription_plans where plan_key=v_sub.plan_key and active=true;
  if not found then
    return query select false,'subscription_plan_unavailable',null::uuid,0,0,0,0,0,now(),now(),v_sub.plan_key;
    return;
  end if;

  v_period_start := date_trunc('month', coalesce(v_sub.current_period_start, now()));
  if v_period_start > now() then
    v_period_start := date_trunc('month', now());
  end if;
  while v_period_start + interval '1 month' <= now() loop
    v_period_start := v_period_start + interval '1 month';
  end loop;
  v_period_end := v_period_start + interval '1 month';

  select coalesce(sum(case when status='consumed' then credits else 0 end),0),
         coalesce(sum(case when status='reserved' then credits else 0 end),0)
    into v_consumed,v_reserved
  from public.ai_credit_ledger
  where user_id=v_user_id and period_start=v_period_start and period_end=v_period_end;

  if v_op.credit_cost=0 then
    return query select true,'no_customer_credit_required',null::uuid,0,greatest(v_plan.monthly_credits-v_consumed-v_reserved,0),v_plan.monthly_credits,v_consumed,v_reserved,v_period_start,v_period_end,v_sub.plan_key;
    return;
  end if;

  if v_consumed + v_reserved + v_op.credit_cost > v_plan.monthly_credits then
    return query select false,'insufficient_ai_credits',null::uuid,v_op.credit_cost,greatest(v_plan.monthly_credits-v_consumed-v_reserved,0),v_plan.monthly_credits,v_consumed,v_reserved,v_period_start,v_period_end,v_sub.plan_key;
    return;
  end if;

  insert into public.ai_credit_ledger(
    user_id,subscription_id,plan_key,period_start,period_end,operation_key,agent_key,execution_id,request_id,credits,status,idempotency_key,metadata
  ) values (
    v_user_id,v_sub.id,v_sub.plan_key,v_period_start,v_period_end,v_op.operation_key,v_op.agent_key,p_execution_id,p_request_id,v_op.credit_cost,'reserved',v_key,coalesce(p_metadata,'{}'::jsonb)
  ) returning id into v_ledger_id;

  return query select true,'credits_reserved',v_ledger_id,v_op.credit_cost,
    v_plan.monthly_credits-v_consumed-v_reserved-v_op.credit_cost,
    v_plan.monthly_credits,v_consumed,v_reserved+v_op.credit_cost,v_period_start,v_period_end,v_sub.plan_key;
end;
$$;

create or replace function public.finalize_ai_credit_charge(
  p_ledger_id uuid,
  p_outcome text,
  p_metadata jsonb default '{}'::jsonb
)
returns table(status text, credits integer, credits_remaining integer, monthly_allowance integer)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := (select auth.uid());
  v_row public.ai_credit_ledger%rowtype;
  v_allowance integer;
  v_consumed integer;
  v_reserved integer;
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;

  select * into v_row from public.ai_credit_ledger where id=p_ledger_id and user_id=v_user_id for update;
  if not found then raise exception 'Credit ledger entry not found'; end if;

  if p_outcome not in ('consumed','released') then raise exception 'Outcome must be consumed or released'; end if;

  if v_row.status <> 'reserved' then
    select monthly_credits into v_allowance from public.ai_agent_subscription_plans where plan_key=v_row.plan_key;
    select coalesce(sum(case when status='consumed' then credits else 0 end),0),
           coalesce(sum(case when status='reserved' then credits else 0 end),0)
      into v_consumed,v_reserved
    from public.ai_credit_ledger where user_id=v_user_id and period_start=v_row.period_start and period_end=v_row.period_end;
    return query select v_row.status,v_row.credits,greatest(v_allowance-v_consumed-v_reserved,0),v_allowance;
    return;
  end if;

  update public.ai_credit_ledger
  set status=p_outcome, metadata=coalesce(metadata,'{}'::jsonb)||coalesce(p_metadata,'{}'::jsonb), updated_at=now()
  where id=v_row.id;

  select monthly_credits into v_allowance from public.ai_agent_subscription_plans where plan_key=v_row.plan_key;
  select coalesce(sum(case when status='consumed' then credits else 0 end),0),
         coalesce(sum(case when status='reserved' then credits else 0 end),0)
    into v_consumed,v_reserved
  from public.ai_credit_ledger where user_id=v_user_id and period_start=v_row.period_start and period_end=v_row.period_end;

  return query select p_outcome,v_row.credits,greatest(v_allowance-v_consumed-v_reserved,0),v_allowance;
end;
$$;

create or replace function public.get_my_ai_credit_status()
returns table (
  plan_key text,
  monthly_allowance integer,
  credits_consumed integer,
  credits_reserved integer,
  credits_remaining integer,
  period_start timestamptz,
  period_end timestamptz
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := (select auth.uid());
  v_sub public.ai_agent_subscriptions%rowtype;
  v_allowance integer := 0;
  v_start timestamptz;
  v_end timestamptz;
  v_consumed integer := 0;
  v_reserved integer := 0;
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;

  select * into v_sub from public.ai_agent_subscriptions
  where user_id=v_user_id and status in ('active','non_renewing')
  order by updated_at desc limit 1;

  if not found then
    return query select null::text,0,0,0,0,now(),now();
    return;
  end if;

  select monthly_credits into v_allowance from public.ai_agent_subscription_plans where plan_key=v_sub.plan_key and active=true;
  v_start := date_trunc('month', coalesce(v_sub.current_period_start,now()));
  while v_start + interval '1 month' <= now() loop v_start := v_start + interval '1 month'; end loop;
  v_end := v_start + interval '1 month';

  select coalesce(sum(case when status='consumed' then credits else 0 end),0),
         coalesce(sum(case when status='reserved' then credits else 0 end),0)
    into v_consumed,v_reserved
  from public.ai_credit_ledger
  where user_id=v_user_id and period_start=v_start and period_end=v_end;

  return query select v_sub.plan_key,v_allowance,v_consumed,v_reserved,greatest(v_allowance-v_consumed-v_reserved,0),v_start,v_end;
end;
$$;

